-- Generated from PDF text extraction; source text is stored in nodes.content.
-- PostgreSQL schema: one row per source PDF, nodes stored as JSONB.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY, title TEXT NOT NULL, original_title TEXT, document_type TEXT NOT NULL, year_bs INTEGER NOT NULL, year_ad INTEGER NOT NULL, total_pages INTEGER NOT NULL, nodes JSONB NOT NULL, source_filename TEXT NOT NULL
);

INSERT INTO legal_documents (id,title,original_title,document_type,year_bs,year_ad,total_pages,nodes,source_filename) VALUES ($CODEx14f2bb8f67$doc_the_labour_act_2017_2074_2017_the_labor_act_2017_2074_pdf$CODEx14f2bb8f67$,$CODExda00c9e717$The Labour Act, 2017 (2074)$CODExda00c9e717$,NULL,$CODEx76f3b5a717$act$CODEx76f3b5a717$,2017,2074,82,$CODEx585f90ccad$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np\nThe Labour Act, 2017 (2074)\nDate of Authentication:\n4 September 2017 (19 Bhadra 2074)\nAct number 14 of the year 2017 (2074)\nAn Act Made for the Amendment and Consolidation of the Laws Relating to\nLabour\nPreamble:\nWhereas, it is expedient to amend and consolidate the laws relating to labour in\norder to provide for rights, interests and benefits of labours, develop good labour relations\nby making explicit provisions on the rights and duties of labours and employers and\nincrease productivity by ending all forms of labour exploitation;\nNow, therefore, the Legislature-Parliament referred to in clause (1) of Article 296\nof the Constitution of Nepal has enacted this Act.", "children": []}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-1", "title": "Chapter-1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short title and commencement: (1) This Act may be cited as the \"Labour Act,", "content": "2017 (2074).\"\n(2) This Act shall commence forthwith.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions: Unless the subject or the context otherwise requires, in this Act:", "content": "(a) \"Basic remuneration\" means the basic remuneration to be received\nby a labour for employment, and this term also include amount of\nincrement in remuneration after completion of one year of the\nemployment period.\n(b) \"Chief Executive\" means a person who bears the final responsibility\nfor the activities of the enterprise.\n(c) \"Workplace\" means the place or location where a labour works, and\nthis term also includes a place or situation where a labour has to stay\nor visit in the course of the work.\n(d) \"Office\" means the Labour Office.\n1\nwww.lawcommission.gov.np\n(e) “Lockout\" means the closure of any enterprise or workplace by the\nemployer to prevent fully or partly the labours from performing their\nregular work.\nProvided that this term does not refer to a situation where the\nlabours are held in reserve or where the work is stopped because of\nthe occurrence of an immediate danger.\n(f) “Prescribed” or “as prescribed” means prescribed or as prescribed\nin the rules framed under this Act, and this term also includes a\nnotice published in the Nepal Gazette as provided for in this Act or\nthe rules framed under this Act.\n(g) \"Inspector\" means the senior labour inspector, labour inspector,\nsenior occupational safety and health inspector and occupational\nsafety and health inspector, and this term also includes any other\nemployee deputed for inspection.\n(h) \"Council\" means the Central Labour Advisory Council formed\npursuant to Section 102.\n(i) \"Remuneration\" means the basic remuneration to which a labour is\nentitled, and this term also includes an allowance.\n(j) \"Enterprise\" means any company, private firm, partnership firm,\ncooperative organization or association or other organization which\nis established, incorporated, registered or formed or operated in\naccordance with the prevailing law with the objective to carry on\nany industry, business or service, with or without profit motive.\n(k) \"Ministry\" means the Ministry of Labour and Employment,\nGovernment of Nepal.\n(l) \"Main employer\" means an employer who employs labours through\na labour provider.\n(m) \"Employer\" means any person or enterprise that employs labours,\nand this term also includes a manager in the case of an enterprise,\nand a labour provider in the case of a labour supplied pursuant to\nthis Act.\n(n) \"Employment contract\" means an agreement entered into between\nan employer and a labour in relation to the service, conditions and\n2\nwww.lawcommission.gov.np\nbenefits of employment, and this term also includes the letter of\nappointment given by the employer to the labour.\n(o) \"Employment period\" means the period during which a labour is\nemployed with an employer, and this term also includes the\nfollowing period:\n(1) Period held in the reserve,\n(2) Period of leave with remuneration,\n(3) Period of unpaid leave taken for maternity or\nmaternity care,\n(4) Period of leave taken for medical treatment in case of\naccident during or while working for the employer.\n(p) \"By-law\" means the by-law relating to conditions of service of the\nlabours framed by an enterprise pursuant to Section 108, and this\nterm also includes the financial administration by-law of the\nenterprise.\n(q) \"Department\" means the Department of Labour.\n(r) \"Manager\" means the chief executive of an enterprise. and this term\nalso includes the chief of any section or unit so appointed as taking\nor exercising the final responsibility or authority.\n(s) \"Managerial level labour\" means a labour appointed to a post at the\nmanagerial or higher level thereof entrusting the authority to\nevaluate, control and supervise the work of labours on behalf of the\nemployer, and this term also includes the manager.\n(t) \"Social Security Fund\" means the Social Security Fund established\npursuant to the prevailing law.\n(u) \"Collective agreement\" means an agreement entered into between\nthe employer or employers' association and the trade union or\nCollective Bargaining Committee on remuneration, conditions of\nservice, benefits of the labours or matters of common concern to the\nemployer and the labours.\n(v) \"Collective Bargaining Committee\" means the Collective\nBargaining Committee referred to in sub-section (1) of Section 116.\n(w) \"Labour Court\" means the Labour Court formed pursuant to Section\n151.\n3\nwww.lawcommission.gov.np\n(x) \"Labour\" means a worker or employee or a person employed with\nany job title who performs a physical or intellectual work for the\nemployer.\n(y) \"Labour supplier\" means a person or body having obtained the\nlicense pursuant to Chapter 11 to supply labours.\n(z) \"Strike\" means a situation where labours collectively refuse to\nperform their regular work partially or completely.\nProvided that a situation where labours are on leave or\nstopped the work as a result of the occurrence of an immediate\ndanger or have become unable to attend or perform the work due to\na situation beyond the control of labours shall not be considered as\na strike.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-2", "title": "Chapter-2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "To remain as minimum standards: (1) This Act shall remain as minimum", "content": "standards for labours and on matters relating to labours.\n(2) Where an employment contract is entered into between an employer\nand a labour with provisions to pay or receive remuneration or benefits lesser than\nthe remuneration or benefits set forth in this Act and the rules framed under this\nAct or in contravention of the conditions set forth in this Act, such an employment\ncontract shall be deemed to be contrary to this Act, and it shall, to that extent, be\nvoid.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "Prohibition on employing in forced labour: (1) No person shall employ any", "content": "labour in forced labour, directly or indirectly.\n(2) Notwithstanding anything contained in sub-section (1), the\nfollowing work or service performed by a labour shall not be deemed to be forced\nlabour:\n(a) Any work or service required to be performed under the duties of\ncitizens as and when the nation so requires,\n(b) Any work or service required to be performed by any person in\nconsideration for the sentence imposed by a decision or order of a\ncourt,\n4\nwww.lawcommission.gov.np\n(c) Any work or service required to be performed as a member of a\ncommunity for the interest of such a community.\nExplanation: For the purpose of this Section, \"forced labour\" means any\nwork or service performed by any labour against his or her will as a result of a\nthreat of taking any action having financial, physical or mental impact if he or she\ndoes not perform such a work or service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "Prohibition on employment of children: No person shall so employ a child in", "content": "any work as to be contrary to law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "Prohibition on discrimination: (1) No employer shall discriminate any labour on", "content": "the ground of religion, colour, sex, caste, tribe, origin, language, ideological\nconviction or other similar ground.\n(2) Notwithstanding anything contained in sub-section (1), the\nfollowing act shall not be considered as discrimination:\n(a) To give preference to any person for employment on the basis of\ninherent requirement of a work or service,\n(b) To engage a female labour who is pregnant in any work or service\nwhich is easier and suitable to her physical condition, without any\nreduction in the remuneration and benefits, or\n(c) To give preference to a labour with physical disability for such job\nresponsibility as is suitable to his or her physical condition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "7", "title": "Prohibition on discrimination in remuneration for equal work: (1) No", "content": "discrimination shall be made between the labours in remuneration for equal value\nof work on the ground of sex.\n(2) For the purpose of sub-section (1), whether the work is of equal\nvalue shall be determined on the basis of the nature of the concerned work, the\ntime required for its performance, labour, skill and productivity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "8", "title": "Right relating to trade union: (1) Every labour shall, subject to this Act and other", "content": "laws, have a right to form and operate a trade union, acquire the membership of,\nor get affiliated with, such union or involve in other activities relating to trade\nunion.\n(2) While exercising the right relating to labour pursuant to this Act and\nother laws, the labour shall be dutiful and responsible towards the employer.\n5\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "9", "title": "Right to remedy: In the event of infringement of any right conferred by this Act", "content": "and other law to a labour, such a labour can get remedy pursuant to this Act or\nother law.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 3", "title": "Chapter- 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "10", "title": "Types of employment: (1) An employer may engage a labour in any type of the", "content": "following employment:\n(a) Regular employment,\n(b) Work-based employment,\n(c) Time-based employment,\n(d) Casual employment,\n(e) Part-time employment.\nExplanation: For the purpose of this Section, -\n(1) “Regular employment” means employment of any type whatever\nother than that set forth in clauses (b), (c) and (d).\n(2) “Work-based employment” means employment that the employer\nprovides or has provided specifying any particular work or service\nfor performance.\n(3) “Time-based employment” means employment that the employer\nprovides or has provided to the labour specifying a certain period on\nthe condition that the labour has to provide any service or perform\nany work within that period.\n(4) “Casual employment” means employment that the employer\nprovides or has provided to the labour on the condition that the\nlabour has to provide any service or perform any work, for seven\ndays or less within a period of one month.\n(5) \"Part-time employment\" means employment that the employer\nprovides or has provided to the labour on the condition that the\nlabour has to perform a work in thirty-five hours or less than thirty-\nfive hours in a week.\n(2) If there arises a question as to whether any employment is regular\nor not, it shall be determined as prescribed on the basis of the nature of the work,\nnotwithstanding anything contained in the employment contract.\n6\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "11", "title": "Prohibition on employment without entering into employment contract: (1)", "content": "No employer shall employ a person without entering into an employment contract.\n(2) Notwithstanding anything contained in sub-section (1), it shall not\nbe necessary to enter into an employment contract in writing for a casual\nemployment.\n(3) While entering into an employment contract pursuant to sub-section\n(1), remuneration, benefits to be received by the labour, conditions of employment\nand other matters as prescribed shall be set out in such a contract.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "12", "title": "Employment relationship to be established: (1) Where the employer enters into", "content": "an employment contract with a labour or employs a labour verbally or engages a\nworker on casual employment, the employment relationship between the employer\nand the employee shall be established, or in the case of the casual employment,\nsuch relation is established from the date or time when the labour is employed or\nhe or she provides the service.\n(2) Where there arises a dispute as to whether the employment\nrelationship has existed between an employer and a labour, such a dispute shall be\nsettled by the Office.\n(3) Where the dispute referred to in sub-section (2) is also included in\nany issue that is sub judice in the Department or a Court, such a dispute shall also\nbe settled by the Department or Court.\n(4) For the purpose of sub-section (2), the Office may give an order to\nthe employer to submit any evidence or document relating to the employment\nwhich remains in his or her custody, and if the employer does not submit such\nevidence or document in pursuance of the order, the employment relationship\nbetween the employer and the labour shall be deemed to have been established.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "Provision relating to probation period: In entering into an employment contract", "content": "with a labour, the employer may so enter into the contract that he or she remains\nin a probation period for six months, and terminate the employment contract with\nthe labour if his or her work is not satisfactory during the probation period. After\nthe end of the probation period of a labour in respect of whom the employment\ncontract has not been so terminated, the employment relation shall ipso facto be\ndeemed to be valid.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "14", "title": "Continuity of existence of the employment relationship despite change in", "content": "ownership: (1) In the case of a change in or transfer of ownership of any work or\n7\nwww.lawcommission.gov.np\nbusiness or any part thereof of any employer or hand over of such a work or\nbusiness to another person for its operation or creation of a new enterprise or\nbusiness as a result of the merger of two or more enterprises or businesses, the\nemployment relationship of the labour working in such an enterprise or business\nthe ownership of which has been so changed or transferred or which has been so\nhanded over to the other person for its operation or in the enterprise or business\nwhich has been merged shall continue to exist.\n(2) For the purpose of sub-section (1), the employer who so undertakes\nthe ownership or acquires the ownership by way of transfer or undertakes\nresponsibility to operate the work or business or, in the case of a merger of\nbusinesses or enterprises, the new enterprise or business created from such merger\nor, in the case of the transfer of the ownership and liability of a project in\naccordance with the prevailing law relating to private investment in the building\nand operation of infrastructures, the enterprise undertaking such ownership and\nliability shall bear the liability under this Act or the rules framed under this Act or\nthe collective agreement, if any, entered into.\nProvided that if any agreement on interim management has been made\nbetween the previous employer, new employer and union of the concerned\nenterprise, the provisions of the agreement shall apply.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "15", "title": "Continuity of existence of employment relationship during the period held in", "content": "reserve: (1) If any special circumstance arises in the workplace, the employer may\nsuspend the work and hold the worker in reserve.\nExplanation: For the purpose of this Section, \"special circumstance\"\nmeans a situation involving the shortage of electricity, water, raw materials or lack\nof financial resources or inability to reach the workplace or work or operate the\nworkplace because of the occurrence of any situation beyond control.\n(2) Where any labour is held in reserve pursuant to sub-section (1), the\nemployment relationship between such an employer and worker shall continue to\nexist.\n(3) Any employer employing ten or more labours may hold the labour\nin reserve for a period not exceeding fifteen days, pursuant to sub-section (1).\nProvided that if it is necessary to hold in reserve for more than the said period, the\nemployer shall consult with the authorised trade union or labour relation\ncommittee.\n8\nwww.lawcommission.gov.np\n(4) Other provisions relating to holding the labour in reserve shall be as\nprescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-4", "title": "Chapter-4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "16", "title": "Trainees may be engaged in work: (1) Any enterprise may, by making an", "content": "agreement with any educational institute, employ any person as an apprentice in\naccordance with the approved curriculum of such an institute.\n(2) The apprentice referred to in sub-section (1) shall not be deemed to\nbe a labour for the purpose of this Act.\nProvided that if the person is employed contrary to the approved\ncurriculum, he or she shall be deemed to be a labour in the regular employment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "Provisions relating to labour to be applicable: (1) Notwithstanding anything", "content": "contained in Section 16, in employing an apprentice pursuant to this Chapter, he\nor she shall not be engaged in work for more than eight hours a day and forty-eight\nhours a week.\n(2) The provisions relating to occupational health and safety shall apply\nto the apprentices as if they were labours.\n(3) Where an apprentice meets with an accident in the course of\nperforming the work of the enterprise, the enterprise shall, unless otherwise agreed\nbetween the enterprise and the educational institute, have medical treatment of\nsuch an apprentice, and provide compensation to him or her if he or she suffers\ngrievous hurt, as if he or she were a labour.\n(4) The matters other than those set forth in sub-sections (1), (2) and (3)\nshall be as mentioned in the agreement between the enterprise and the educational\ninstitute.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "18", "title": "Engagement in work as trainee labour: (1) An employer may employ any person", "content": "as a trainee providing on the job training.\n(2) The period of training referred to in sub-section (1) shall not be more\nthan one year.\nProvided that any period is specified by the prevailing law for a specific\nwork or specific training period is required for it, a trainee may accordingly be\nemployed for that period.\n9\nwww.lawcommission.gov.np\n(3) The employer shall provide the person employed a trainee pursuant\nto this Section with at least such facilities as may not be less than the minimum\nremuneration and other social security benefits including the sick leave, gratuity,\nprovident fund and insurance.\n(4) The employer shall not be compelled to continue the employment of\nthe trainee after the completion of the training period.\nProvided that if the same employer engages the trainee in work, the\nprobation period shall not apply to him or her.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-5", "title": "Chapter-5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "19", "title": "Part-time employment: (1) An employer may employ a labour for part time.", "content": "Provided that a worker who works full time shall not be employed in part-\ntime work without his or her consent.\n(2) The remuneration of part time labours shall be fixed generally on\nthe basis of working time (hours) or on the basis of the employment contract\nentered into between the two parties.\n(3) While fixing the remuneration of the part time labours pursuant to\nsub-section (2), such remuneration shall be fixed on the basis of at least the\nmonthly remuneration of the labours working full time at the same level for the\nwork of same nature.\n(4) Where a labour employed part-time pursuant to this Section is\nemployed in the overtime work, such a labour shall be provided with a\nremuneration that is 1.5 times of the remuneration to which he or she is entitled\nunder sub-section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "20", "title": "Not to restrain from working elsewhere: No part time labour shall be restrained", "content": "from working elsewhere.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "21", "title": "Provisions relating to social security: In the case of a part-time labour who works", "content": "for more than one employer, each employer shall, on the basis of the basic\nremuneration to which the labour is entitled, make contribution for gratuity,\nprovident fund or other social security related benefits.\n10\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-6", "title": "Chapter-6", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "22", "title": "Restriction on employment of foreigners: (1) No employer shall employ any", "content": "foreign citizen as a labour without obtaining the work permit from the Department.\n(2) Notwithstanding anything contained in sub-section (1), the\nemployer may, if the skilled labour that it needs cannot be supplied from among\nNepali citizens, employ a foreign labour subject to this Section.\n(3) Prior to employing a foreign labour pursuant to sub-section (2), the\nemployer shall publish an advertisement in a national daily newspaper in order to\nacquire the required skilled labour from among the Nepali citizens. If, in spite of\nsuch an advertisement, no application is received from any Nepali citizen as\nprescribed or any Nepali citizen cannot be selected, the employer may make an\napplication, accompanied by the evidence thereof, to the Department for the work\npermit for employing a foreign labour.\n(4) The Department may, if it deems reasonable upon inquiring into the\napplication received under sub-section (3) and the evidence attached therewith,\nissue a work permit for the employment of a foreign skilled labour.\n(5) Any employer who employs a foreign labour by obtaining the work\npermit pursuant to sub-section (4) shall make arrangement for making Nepali\ncitizens skilled and gradual replacement of foreign labours.\n(6) The fees and other provisions relating to the work permit shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "23", "title": "Foreign citizen to obtain work permit to work in Nepal: (1) A foreign labour", "content": "shall obtain the work permit as prescribed in order to work in Nepal.\n(2) Notwithstanding anything contained elsewhere in this Act, any\nforeign citizen who work in Nepal shall, except where he or she is entitled to\ndiplomatic immunity or is not required to obtain a work permit under any treaty\nor agreement concluded with the Government of Nepal, obtain a work permit as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Work permit may be issued: Notwithstanding anything contained in Sections 22", "content": "and 23, the Department may, upon maintaining the records, issue the work permit\nto foreign nationals in the following circumstance:\n11\nwww.lawcommission.gov.np\n(a) The chief executive of an enterprise with foreign investment or\noperated with foreign assistance and such number of labours as\nprescribed to work in that enterprise,\n(b) Any technician who comes to repair or maintain any machinery\nobject or install any new technology or to do similar other unforeseen work for a\nperiod of three months or less than three months.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Language of the contract: While entering into the employment contract with a", "content": "foreign labour and providing information relating to the work to be performed by\nhim or her, conditions of his or her service and benefits, the employer shall enter\ninto, or cause to be entered into, such a contract or provide such information in\nsuch a language that he or she understands or in the English language.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Remuneration may be repatriated in convertible foreign currency: Any", "content": "foreign labour who has obtained the work permit pursuant to this Chapter shall be\nallowed to repatriate to his or her country the amount of remuneration earned by\nworking in Nepal in a convertible foreign currency.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "Remuneration, conditions of service, benefits of and other provisions relating", "content": "to foreign labours: (1) The remuneration to which a foreign labour is entitled for\nthe work performed, conditions of service and benefits of him or her shall be so\nmentioned in the time-based or task-based employment contract entered into\nbetween the employer and the labour as not being less favourable than the\nstandards set by this Act or the rules framed under this Act.\n(2) The employment contract shall remain valid for such a period as\nmentioned in that contract, and failing such a provision, for a period not exceeding\nthree years.\n(3) Other provisions relating to foreign labours shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-7", "title": "Chapter-7", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "28", "title": "Working hours: (1) No employer shall employ labours to work more than eight", "content": "hours a day and forty-eight hours a week.\n(2) The labours shall be provided with half an hour rest after five\nhours of continuous work.\n(3) In the cases of work which is not to be stopped and is to be carried\nout continuously, labours shall be provided with such a rest time turn by turn.\n12\nwww.lawcommission.gov.np\n(4) The rest time to be provided pursuant to sub-sections (2) and (3)\nshall be counted in the working hours referred to in sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "29", "title": "Not to compel to work overtime: (1) No employer shall compel a labour to work", "content": "more than the hours set forth in sub-section (1) of Section 28.\n(2) Notwithstanding anything contained in sub-section (1), if the non-\nperformance of a work is likely to cause an adverse effect on the life, safety and\nhealth of any person or a serious loss or damage to the employer, the concerned\nlabour may, subject to sub-section (1) of Section 30, be caused to work overtime.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "30", "title": "Provisions relating to overtime: (1) Where an employer needs to cause any", "content": "labour to work for more than the working hours specified subject to Section 28,\nsuch a labour may be caused to work not exceeding four hours a day and twenty-\nfour hours a week.\n(2) The work which any labour has been caused by the employer to\nperform without giving the substitute leave pursuant to Section 42 shall be deemed\nto be an overtime work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "31", "title": "Additional remuneration to be paid: (1) While employing any labour to work", "content": "overtime pursuant to Section 30, the employer shall pay to the labour remuneration\nat a rate of 1.5 times of the basic remuneration receivable during regular hours of\nwork.\n(2) Notwithstanding anything contained in sub-section (1), nothing\ncontained in this Section shall bar the collective agreement to provide for certain\nbenefits or the providing of such benefits as mentioned in the employment contract\nin the case of the labour of managerial level, in lieu of the additional remuneration\nreceivable for an overtime work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "32", "title": "Fixation of working hours: (1) Where an employment contract specifies the", "content": "starting and finishing time of working hours for workers, it shall be followed\naccordingly or in its absence, it shall be as determined by the employer.\n(2) Other provisions relating to working hours shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "33", "title": "Arrangement for transportation to be made: In employing a female labour", "content": "where the working hours begin after the sunset or before the sun rise, the employer\nshall make necessary arrangement for transportation to and from the workplace.\n13\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-8", "title": "Chapter-8", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "34", "title": "Entitlement of labours to remuneration: (1) Each worker shall be entitled to", "content": "receive the remuneration and benefits from the date on which he or she starts the\nwork.\n(2) The remuneration and benefits which a labour is entitled to shall be\nso specified in the employment contract as not to be less than that specified in this\nAct and the rules framed under this Act.\n(3) Except as mentioned in the collective agreement between the\nemployer and the labour, the remuneration and benefits being received and\nenjoyed by the labour shall not be decreased.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "35", "title": "Payment of remuneration: (1) In paying the remuneration to the labour, the", "content": "employer shall make such payment in accordance with the provision, if any,\nmentioned in the employment contract to that effect, and failing such a provision,\nat such a time as determined by the employer.\nProvided that the remuneration shall be paid as follows to the following\nlabour:\n(a) In the case of a labour working for a period of less than one month,\nwithin three days from the date of completion of the work.\n(b) In the case of a labour employed in a casual work, immediately after\nthe completion of the work.\n(2) Notwithstanding anything contained in sub-section (1), the interval\nbetween the dates for payment of remuneration shall not be more than one month.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "36", "title": "Entitlement to annual increment in remuneration (grade): Any labour who has", "content": "completed one year of service period shall be entitled to an annual increment in\nremuneration (grade) each year in an amount equal to at least half a day\nremuneration based on the monthly basic remuneration to which the labour is\nentitled.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "37", "title": "Entitlement to festival expense: (1) Each labour shall be entitled to an amount", "content": "equal to the basic remuneration of one month as the festival expense each year for\nthe festival to be celebrated according to his or her religion, culture and tradition.\n(2) A labour may make a written request to the employer for the\npayment of the festival expense referred to in sub-section (1) at one time in one\nfiscal year on the occasion of the main festival to be celebrated according to his\n14\nwww.lawcommission.gov.np\nor her religion, culture and tradition. In the case absent such a request, the festival\nexpense shall be provided at the time of Dashain festival every year.\n(3) A labour who has not completed one year of service period on or\nbefore the day of payment of the festival expense shall be entitled to such expense\nin proportion to the period of service he or she has completed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "38", "title": "Prohibition on deduction of remuneration: (1) Except in the following", "content": "circumstance, no amount shall be deducted from the remuneration receivable by\nthe labour:\n(a) Any tax, fees leviable under law,\n(b) Any amount of contribution required to be made for provident fund\nor insurance or any other social security,\n(c) Any amount required to be deducted pursuant to the order or\ndecision by any judicial or quasi-judicial body or arbitration,\n(d) Such amount as prescribed for such service or facility provided by\nthe employer to the labour as prescribed,\n(e) Amount of remuneration for the period during which the labour\nremains absent from the work,\n(f) In the event of loss of or damage to cash or in-kind of the employer\nwith ulterior motive or recklessly, such amount as mentioned in the\ncash or in-kind book or the amount equivalent to the production cost\nin the case of a manufactured good,\n(g) Such amount as specified in the collective agreement to be\ndeductible from remuneration,\n(h) Membership fee chargeable by the trade union,\n(i) Amount of loan or advance provided or paid to the labour by the\nemployer.\n(2) While deducting the amount pursuant to sub-section (c), (d), (e), (f),\n(g), (h) or (i), it shall be deducted from the monthly remuneration that remains\nafter deducting the amounts set forth in sub-sections (a) and (b).\n(3) The limit of, procedure and other provisions relating to the amount\ndeductible under sub-section (2) shall be as prescribed.\n(4) Where a labour dies or is relieved of service for any reason\nwhatsoever before the amount deductible pursuant to this Section is deducted, such\nan amount may be deducted from any amount whatsoever payable to such a labour.\n15\nwww.lawcommission.gov.np\n(5) Where the amount to be deducted cannot be recovered even after\nmaking deductions pursuant to sub-section (4) and the labour has died, the\nemployer shall give a notice of fifteen days to his or her heir under the law for the\npayment of such an amount.\n(6) Where the amount is not paid even within the period referred to in\nsub-section (5), the employer may make a petition to the court for the recovery of\nsuch an amount within thirty-five days of the expiry of the period.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "39", "title": "Remuneration for reserve period: Where a labour is held in reserve pursuant to", "content": "this Act, the employer shall pay half the remuneration which he or she is entitled\nto until the work is resumed.\nProvided that such a labour shall not be required to make attendance in the\nworkplace during the reserve period unless the requirement of attendance is\nmentioned in the notice on holding the labour in reserve.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 9", "title": "Chapter- 9", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "40", "title": "Weekly leave: A labour shall get the weekly leave of one day in each month.", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "41", "title": "Public leave: (1) Each labour shall each year get a paid public leave of thirteen", "content": "days including the May Day, and fourteen days including International Women\nLabour Day in the case of a female labour.\n(2) Notwithstanding anything contained in sub-section (1), the public\nholidays in the case of an enterprise shall be as determined by the regulatory\nauthority, if any, that regulates such an enterprise and as determined by the\nemployer in the other situations.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "42", "title": "Substitute leave: (1) A labour who is involved in a work that must not be stopped", "content": "or must be done continuously shall get the substitute leave in consideration for\nhaving worked on any day of weekly or public leave.\n(2) Any labour who has been engaged in work on a day of weekly or\npublic leave shall be provided with the substitute leave within twenty-one days of\nthe date of engagement in work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "43", "title": "Home leave: (1) Every labour shall get paid home leave at the rate of one day for", "content": "twenty days of the period he or she has worked.\n(2) A labour who is employed in an educational institution or who gets\nsummer or winter leave shall not get home leave.\n16\nwww.lawcommission.gov.np\nProvided that where such leave is lesser than the period of home leave, the\nlabour shall get home leave for such number of days as is so lesser.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "44", "title": "Sick leave: (1) A labour shall get paid sick leave of twelve days a year.", "content": "Provided that a labour who work for a period of one year or lesser than one\nyear shall get the sick leave proportionately.\n(2) A labour who seeks the sick leave for more than three consecutive\ndays shall submit a certificate on his or her medical check-up by a recognized\ndoctor.\n(3) Where a labour has to take leave because of sudden illness, the\nlabour shall inform the employer or the person specified by the employer through\nthe fastest means to the extent available.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "45", "title": "Maternity leave: (1) A pregnant female labour shall get a maternity leave of a", "content": "total of fourteen weeks before or after delivery.\n(2) A pregnant labour shall compulsorily take leave from at least two\nweeks before the expected date of delivery to at least six weeks after the date of\ndelivery.\n(3) A female labour who takes the maternity leave referred to in sub-\nsection (1) shall get full remuneration for sixty days and shall not get remuneration\nfor the remaining period.\n(4) Where a recognized medical doctor recommends that the female\nlabour who has delivered a baby needs further rest for her or her baby’s health, the\nemployer shall approve unpaid leave of up to one month in addition to the period\nreferred to in sub-section (1) or sanction such leave to be adjusted with other leave,\nin continuity with the maternity leave.\n(5) Where a female labour in a state of seven months’ pregnancy or\nmore than seven months gives birth to a deceased child or suffers miscarriage, she\nshall get leave as if she made normal delivery.\n(6) Where the mother dies before the completion of sixty days of the\nbirth of her child, the labour whose wife has so died may take paid leave for the\nremaining period for the care of the child from the employer for whom he is\nworking.\n(7) If a male labour’s wife is going to deliver a baby, he shall get paid\nmaternity care leave for a period of fifteen days.\n17\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "46", "title": "Birth registration certificate to be submitted: Except where a newly born child", "content": "dies, a female worker who is on maternity leave shall submit a copy of such birth\nregistration certificate as prescribed to the employer.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "47", "title": "Remuneration need not be paid: Notwithstanding anything contained elsewhere", "content": "in this Chapter, where a provision is made that a female labour is to receive\nremuneration for the period of maternity leave from the Social Security Fund, the\nemployer shall not be required to pay, to that extent, the remuneration referred to\nin this Chapter to the labour for such a period of leave.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "48", "title": "Mourning leave: (1) Where a labour himself or herself has to mourn according to", "content": "his or her religion or because her husband or his wife dies or a married female\nworker has to mourn on the death of her father or mother or father-in-law or\nmother-in-law, such a labour shall get a mourning leave of thirteen days.\n(2) The labour who goes on the mourning leave referred to in sub-\nsection (1) shall get full remuneration.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "49", "title": "Accumulation of leave: (1) A labour is entitled to accumulate the home leave and", "content": "the sick leave for up to ninety days and forty-five days, respectively.\n(2) Where a labour is relieved of the service for any reason or dies, he\nor she or such family member of him or her as prescribed shall get the lump sum\namount to be set by the last basic remuneration being drawn by him or her for his\nor her accumulated home leave and sick leave.\n(3) A labour whose accumulated leave exceeds the period specified in\nsub-section (1) shall, at the end of each year, get the amount to be set by his or her\nbasic remuneration for the leave of such excess period.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "50", "title": "Computation of year: A year shall, for the purpose of leave, be computed on the", "content": "following basis:\n(a) Where it is determined by law, it shall be in accordance with such\nlaw,\n(b) Where it is determined by the regulatory body, it shall be in\naccordance with such provision,\n(c) Where it is not determined pursuant to clause (a) or (b), it shall be\nas set out in the employment contract,\n(d) Where it is not determined as set forth in clauses (a), (b) and (c), it\nshall be in accordance with the financial year of the Government of\nNepal.\n18\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "51", "title": "Leave not as a matter of right: (1) All leaves except the sick leave, mourning", "content": "leave and maternity leave which the labour is entitled to pursuant to this Chapter\nare only facility and cannot be claimed as a matter of right.\n(2) In the case of leaves other than that mentioned in sub-section (1),\nthe employer may, for the reason to be specified, refuse, withhold, deduct or alter\nthe time of the approved leave, on the basis of the need of the work at the\nworkplace.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-10", "title": "Chapter-10", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "52", "title": "Contribution for provident fund: (1) The employer shall deduct ten percent of", "content": "the basic remuneration of each labour, add cent percent to that amount and deposit\nthe total amount for the purpose of provident fund.\n(2) The employer shall deposit the amount referred to in sub-section (1)\nin the Social Security Fund in the name of the concerned labour, with effect from\nthe date on which he or she started to work.\n(3) Notwithstanding anything contained in the sub-section (2), the\nemployer shall, in the following circumstance, deposit such provident fund amount\nas prescribed:\n(a) Until the Social Security Fund is established and comes into\noperation, or\n(b) Until the law relating to the Social Security Fund becomes\napplicable to the concerned employer.\n(4) In the case of a labour for whom the amount for provident fund was\nnot contributed before the commencement of this Act, the employer shall\ncontribute the amount for provident fund from the date of the commencement of\nthis Act.\n(5) The amount for the provident fund deposited in the retirement fund\nor any other similar fund established under the laws in force at the time of the\ncommencement of this Act or held in the custody of the employer shall be\ntransferred to the Social Security Fund as prescribed after the commencement of\nthis Act.\n(6) Notwithstanding anything contained elsewhere in this Section, the\nemployer shall make payment of an additional amount equivalent to ten percent of\n19\nwww.lawcommission.gov.np\nthe basic remuneration of such a labour if the amount for the provident fund cannot\nbe deposited pursuant to Section (2) or (3) for any reason.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "53", "title": "To receive gratuity: (1) The employer shall deduct an amount equivalent to eight", "content": "point three and three (8.33) percent of the basic remuneration of each labour each\nmonth and deposit it for the purpose of gratuity.\n(2) The amount referred to in sub-section (1) shall be deposited in the\nSocial Security Fund in the name of the concerned labour with effect from the date\non which such a labour begins to work.\n(3) Notwithstanding anything contained in sub-section (2), the\nemployer shall, in the following circumstance, deposit such amount of gratuity as\nprescribed:\n(a) Until the Social Security Fund is established and comes into\noperation, or\n(b) Until the law relating to the Social Security Fund is applicable to\nthe concerned employer.\n(4) The employer shall provide the gratuity referred to in sub-section\n(1) from the date of the commencement of this Act in the case of a labour whom\nthe gratuity is not required to be paid to before the commencement of this Act.\n(5) The amount for gratuity deposited in the retirement fund or any\nother similar fund established under the laws in force at the time of the\ncommencement of this Act or held in the custody of the employer shall be\ntransferred to the Social Security Fund as prescribed after the commencement of\nthis Act.\n(6) Notwithstanding anything contained elsewhere in this Section, the\nemployer shall pay to a labour an additional amount equivalent to eight point three\nand three (8.33) percent of the basic remuneration of such a labour if the amount\nfor gratuity cannot be deposited for any reason pursuant to sub-section (2) or (3).\n(7) Any labour who is entitled to pension shall not get the gratuity\nreferred to in this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "54", "title": "Medical insurance to be made: (1) The employer shall procure make an annual", "content": "medical insurance of at least one hundred thousand rupees for each labour.\n(2) The premium required for the medical insurance referred to in sub-\nsection (1) shall be borne by both the employer and the labour on pro rata basis.\n20\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "55", "title": "Accidental insurance to be made: (1) The employer shall procure accidental", "content": "insurance of at least seven hundred thousand rupees covering all kinds of accidents\nfor each labour.\n(2) The whole premium required for the accidental insurance referred\nto in sub-section (1) shall be borne by the employer.\n(3) If a labour dies or gets completely incapacitated mentally or\nphysically as a result of an accident, such a labour or his or her legal heir under\nthe prevailing law shall get for compensation the cent percent of the amount of\ninsurance referred to in sub-section (1).\n(4) If a labour gets injured or incapacitated in an accident, he or she\nshall get compensation on the basis of the percentage of incapacitation as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "56", "title": "Amount to be paid by the employer: Where a labour or his or her dependent heir", "content": "is not able to obtain the amount of insurance because of the failure of the employer\nto procure insurance referred to in this Chapter or any recklessness or error made\nin the making of insurance, the employer shall pay an amount equivalent to the\ninsurance to such a labour or dependent heir. \\", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "57", "title": "Social security scheme to be applicable: Any employer or labour who so makes", "content": "contribution in the social security scheme as to be entitled to the benefits including\nthe provident fund, gratuity and medical insurance pursuant to the law relating to\nthe Social Security Fund shall not be required to make additional contribution or\ninsurance under this Chapter, to the extent of such contribution.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter- 11", "title": "Chapter- 11", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "58", "title": "Labours may be employed through supplier: (1) The Ministry shall, on", "content": "recommendation of the Council, publish a list of works in which labours may be\nemployed through labour suppliers, by publishing a notification in the Nepal\nGazette.\n(2) While employing a labour through a labour supplier pursuant to sub-\nsection (1), the employer shall employ him or her in any work other than the core\nwork of the business or service.\n(3) While inviting or submitting any kind of proposal or tender for the\npurpose of supplying or causing to supply a labour through a labour supplier or\n21\nwww.lawcommission.gov.np\nentering into an agreement for the supply of labour, such proposal or tender or\nagreement shall be invited or submitted or entered into so that the remuneration\nand other benefits of the labour to be supplied shall not be less than that specified\nin this Act.\n(4) Any proposal or tender invited or submitted or agreement entered\ninto contrary to sub-section (3) shall ipso facto be invalid.\nExplanation: For the purpose of this Section, \"core work\" means the work\nmentioned while establishing the business and work directly related thereto.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "59", "title": "License to be obtained: (1) A company that wishes to supply labours shall obtain", "content": "a license pursuant to this Act.\nExplanation: For the purpose of this Chapter, \"company\" means any\ncompany incorporated in accordance with law.\n(2) A company that wishes to obtain a license shall make an application\nin the prescribed format, accompanied by such fees, details and documents as\nprescribed, to the Office of the concerned area.\nProvided that a company that wishes to supply labours in an area with more\nthan one Offices shall make an application in the prescribed format, accompanied\nby such fees, details and documents as prescribed, to the Department in order to\nobtain the license.\n(3) If the content of an application received pursuant to sub-section (2)\nseems to be reasonable upon its examination, the Department or Office shall, by\ntaking such a deposit or bank guarantee as prescribed, issue the license to such an\napplicant on such conditions and in such a format as prescribed not later than\nfifteen days.\n(4) While issuing a license pursuant to sub-section (3), the work or\nservice and scope of work relating to the supply of labours shall be mentioned in\nsuch a license.\nProvided that the same company shall not be allowed to supply labours for\nmore than two works or services.\n(5) Any organization or person carrying out labour supply related\nbusiness at the time of commencement of this Act shall, not later than six months\nfrom the date of commencement of this Act, incorporate a company carrying out\nthe business of supplying labours in accordance with the prevailing company law\nand obtain the license pursuant to this Section.\n22\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "60", "title": "Submission of details by licensee: A licensee who has obtained a license from", "content": "the Office shall submit to the Office, and a licensee who has obtained a license\nfrom the Department shall submit to the Department, such details as prescribed\nbefore the last day of the month of Poush (mid January) each year.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "61", "title": "Obligations of labour supplier: (1) The labour supplier shall not perform acts", "content": "and actions contrary to the conditions or directions as prescribed under this Act or\nthe rules framed under this Act.\n(2) The labour supplier shall, in the capacity of the employer referred\nto in this Act, provide such remuneration and other benefits regularly to the labour\nit supplies as may not be less than that determined under this Act.\n(3) The labour supplier shall regularly obtain information as to whether\nor not the main employer has taken or made such measures and provisions or\narrangements as required to be taken or made in the workplace for occupational\nsafety and health of the labour, and recommend for making such arrangements\nimmediately if it is found that such arrangements have not been made.\n(4) Where it is found that the main employer has not implemented the\nrecommendation referred to in sub-section (3), the labour supplier shall give\ninformation thereof to the Department or concerned Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "62", "title": "Revocation, suspension of license or fine: (1) The Department or Office issuing", "content": "the license may revoke the licence of a labour supplier in the following\ncircumstance:\n(a) If the labour supplier makes an application in writing for the\nrevocation of his or her license, or\n(b) If, in spite of the fine imposed pursuant to sub-section (6), the labour\nsupplier continues to violate the conditions specified or directions\nissued pursuant to this Act or the rules framed under this Act.\n(2) Prior to the revocation of a license pursuant to clause (b) of sub-\nsection (1), the concerned labour supplier shall be provided with an opportunity\nof at least seven days to furnish his or her explanation.\n(3) A notice on the decision made to revoke the license pursuant to this\nSection shall be published publicly.\n(4) Notwithstanding anything contained elsewhere in this Section, if it\nappears that the labour supplier whose license has been revoked has any financial\nliability towards the Government of Nepal or any labour, he or she shall not get\n23\nwww.lawcommission.gov.np\nimmunity from the performance of such liability by the reason of the revocation\nof the license.\n(5) The Department or Office may suspend as prescribed the license of\nany labour supplier if such a labour supplier fails to comply with the terms\nspecified in and directions given under this Act and the rules framed under this\nAct.\n(6) If any labour supplier fails to comply with the terms specified in and\ndirections given under this Act and the rules framed under this Act, the Department\nor Office may impose on such a labour supplier a fine not exceeding twenty-five\nthousand rupees for the first time.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "63", "title": "Payment of remuneration and other benefits: (1) In the event of revocation of", "content": "the license of a labour supplier, such a labour supplier shall pay such amount of\nremuneration and other benefits as is payable to a labour within fifteen days.\n(2) In the event of failure to pay the amount of remuneration and other\nbenefits receivable by a labour within the period specified in sub-section (1), the\nDepartment or Office that has issued the license shall arrange the payment of such\namount from the deposit or bank guarantee furnished or given by such a labour\nsupplier to such a labour at the time of obtaining the license.\n(3) Where the amount of deposit or bank guarantee is not sufficient to\npay the remuneration and other benefits pursuant to sub-section (2), the payment\nshall be made on pro rata basis. If such a labour supplier body is liquidated or\ndissolved, payment of the remaining remuneration and other benefits shall be made\nin accordance with the prevailing law. If such a body is continuing other activities\nwithout being dissolved or liquidated, the Office shall give an order for the\npayment of such remuneration and benefits from its other properties.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "64", "title": "Obligations of the main employer: (1) The main employer shall, while", "content": "employing a labour through a licensee labour supplier, so employ him or her in\naccordance with the agreement entered with such a labour supplier.\n(2) The main employer shall, before entering into the agreement,\narrange for the provision of such remuneration and benefits as may not be less\nthan that specified in this Act or the rules framed under this Act to the labour.\n(3) The main employer shall regularly obtain information as to whether\nor not the labour supplier has provided the remuneration and benefits regularly to\nthe labour employed through such a labour supplier.\n24\nwww.lawcommission.gov.np\n(4) If, while obtaining information pursuant to sub-section (3), it is\nfound that the labour supplier has not provided the remuneration and benefits to\nthe labour, the main employer shall immediately recommend the labour supplier\nto provide such remuneration and benefits and give information thereof to the\nDepartment or Office as well.\n(5) If the labour supplier fails to provide the remuneration and benefits\nto the labour in spite of the request made pursuant to sub-section (4), the main\nemployer shall give information thereof to the Department or Office.\n(6) If information is received pursuant to sub-section (5) or information\nis received through any other means about the labour supplier’s failure to provide\nthe remuneration and benefits to a labour, the Department or Office may make\npayment from the deposit or bank guarantee furnished by such a labour supplier\nat the time of obtaining the license.\n(7) The main employer shall take or make such measures and provisions\nor arrangements as required to be taken or made at the workplace for occupational\nsafety and health.\n(8) If the remuneration or benefits to be provided to the labour pursuant\nto the prevailing law increase after the agreement between the labour supplier and\nthe main employer has been made, the main employer shall add and pay such\nincreased remuneration or benefits.\n(9) No labour shall be supplied from any enterprise established with the\ninvolvement of the main employer or of any manager or director or family\nmember, on his or her behalf.\n(10) Other provisions relating to the obligations of the main employer\nshall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "65", "title": "To make inspection, supervision and monitoring: (1) The Office shall regularly", "content": "make inspection and monitoring as to whether or not the labour supplier has acted\nin accordance with this Act or the rules framed under this Act and the directions\nand conditions given and prescribed pursuant to this Act and the rules framed\nunder this Act.\n(2) If it is found from an on-site inspection, monitoring or any other\nmeans that any labour supplier has not acted pursuant to this Act and the rules\nframed under this Act or the conditions specified as applicable to him or her, the\nOffice may give necessary direction to the labour supplier.\n25\nwww.lawcommission.gov.np\n(3) It shall be the duty of the concerned labour supplier to comply with\nthe direction given pursuant to sub-section (2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "66", "title": "Liability of labours to rest on the main employer: Where any main employer", "content": "employs any labour by supplying such a labour through a person or company who\nhas not obtained the license to supply labours pursuant to this Act or contrary to\nthe provisions of this Act, such a labour shall be deemed to be a labour of the main\nemployer.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "67", "title": "Prohibition on collecting fee from labour: No labour supplier shall collect any", "content": "kind of fee or commission from any labour whom it has supplied.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-12", "title": "Chapter-12", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "68", "title": "Formulation of safety and health Policy: (1) Subject to the provisions of this", "content": "Act, the rules framed under this Act and directions given pursuant to this Act and\nthe rules framed under this Act, the employer shall formulate and implement a\npolicy on safety and health of the labours and other persons at the workplace.\n(2) The policy formulated pursuant to sub-section (1) shall be registered\nwith the Office.\n(3) Other provisions relating to the safety and health policy to be\nformulated by the employer shall be as prescribed.\n(4) The Office shall regularly monitor as to whether or not the safety\nand health policy formulated by the employer under this Section has been\ncomplied with.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "69", "title": "Duties of employer towards labour: (1) The duties of the employer towards the", "content": "labour in respect of occupational safety and health shall be as follows:\n(a) To make safe environment for work by making appropriate\nsafety and health arrangements at the workplace,\n(b) To make provision for the use, operation, storing and\ntransportation of chemical, physical or biological materials\nor equipment so that it would not adversely affect the safety\nand health,\n(c) To provide necessary information, notice and training\nrelating to the safety and health to the labour, as required,\n26\nwww.lawcommission.gov.np\n(d) To provide necessary training and information in an\nappropriate language to the labour in relation to the use and\noperation of the equipment or chemical, physical or\nbiological materials related to the work,\n(e) To make proper arrangement for the safe entry and exit from\nthe workplace,\n(f) To provide personal safety means to the labour, as required,\nand\n(g) To make such other provisions as prescribed.\n(2) The employer shall not collect any fee or charge from a labour in\nconsideration for the provision of any safety related facility or equipment to the\nlabour.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "70", "title": "Duties of employer towards non-labour: (1) The employer shall make such", "content": "provision as may be necessary to avoid any adverse effect on the safety and health\nof any non-labour who walks in and out of, or passes through, the workplace.\n(2) Where any operating system of the workplace is likely to cause any\nharmful effect or risk on the safety or health of any person, the employer shall\nmake arrangement for giving, putting a signal or providing information in that\nrespect.\n(3) Any enterprise that uses or manufactures chemical materials shall\nso manage that the chemical substance, gas or any other thing emitting during the\noperation of its business does not cause any adverse effect on the local animals,\nvegetation, human beings and environment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "71", "title": "Duties of the responsible person: (1) It shall be the duty of the responsible person", "content": "to ensure whether any workplace, equipment, product or material is safe and\nhealthy for the concerned work.\nExplanation: For the purpose of this Section, \"responsible person\" means\nany person who has the ownership or control over the workplace, equipment,\nproduct or material, and this term also includes any person or organization\nassigned with the ownership or control in accordance with the agreement, if any,\nmade in relation to the chief of such a workplace, use of the equipment, product\nor material.\n27\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "72", "title": "Duties of manufacturers, importers and suppliers: (1) The duties of the", "content": "manufacturer, importer or supplier of any equipment, product or material to be\nused at the workplace shall be as follows:\n(a) To manufacture, import and supply equipment, product or material\nfound suitable from the examination for the operation and use at the\nworkplace from the viewpoint of safety and health;\n(b) To determine such a method or process for using or operating such\nequipment, product or material properly so that the safety and health\nof the concerned persons at the workplace is not affected adversely,\n(c) To identify possible risks of causing adverse effect on the safety\nand health by the use of such equipment, product or material,\n(d) To conduct necessary research, use or experiment to eliminate or\nminimize the risks identified pursuant to clause (c),\nProvided that where there is a reasonable ground to believe\nin the results of any research, use or experiment conducted earlier\nby any other person such a research, use or experiment may be given\nrecognition.\n(e) To prepare a manual in order to provide all the information relating\nto the necessary measures required to be taken, from the viewpoint\nof safety and health, during the operation and use of the equipment,\nproduct or material to be operated or used at the workplace.\n(2) A person or organization that manufactures or installs any\nequipment to be used in the workplace shall give the employer a report in writing\nto the effect that such equipment so manufactured or installed, if used properly,\nwill not cause any adverse effect on the safety or health of any person.\n(3) If any equipment, product or material is not used in accordance with\nthe information or instruction provided by the manufacturer or supplier providing\nsuch equipment, product or material in relation to the use of the equipment,\nproduct or material, such equipment or material shall, for the purpose of this\nSection, not be deemed to have been used properly.\n(4) The manufacturer, importer or supplier of any chemical material to\nbe used in the workplace shall provide the employer with such other details\nincluding the chemical safety data sheet in relation such material as prescribed.\n28\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "73", "title": "Duties of labour: (1) The duties of the labour in relation to occupational safety", "content": "and health shall be as follows:\n(a) Not to perform any such act in the workplace intentionally or\nrecklessly that may cause adverse effect or risk on the safety\nand health of him or her or of others,\n(b) To provide necessary assistance to the employer and\nconcerned person in the fulfilment of any duties mentioned\nin this Chapter,\n(c) To obtain information about the manuals, instructions and\nother matters prepared for the operation and use of the\nequipment, product or material to be operated and used in the\nworkplace safely and cautiously,\n(d) To operate and use the workplace, equipment, product or\nmaterial safely and cautiously in accordance with the\nmanuals, information and instructions prepared for the\noperation and use of such a workplace, equipment, product\nor material, and\n(e) To use compulsorily the personal safety equipment provided\nby the employer.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "74", "title": "To form safety and health committee: (1) The employer shall form such a safety", "content": "and health committee with representation of the labours also as prescribed in an\nenterprise where twenty or more labours are employed.\n(2) For the purpose of sub-section (1), the labours employed through a\nlabour supplier shall also be counted.\n(3) The functions, duties and powers of the safety and health committee\nformed pursuant to sub-section (1) shall be as follows:\n(a) To give advice to the employer regularly on the arrangement\non safety and health required to be made in the workplace\nand on making such an arrangement effective,\n(b) To evaluate the arrangement on safety and health made in the\nworkplace, and draw the attention of the employer for\nmaking such an arrangement more effective,\n29\nwww.lawcommission.gov.np\n(c) In the event of failure to do the act in spite of the attention\ndrawn pursuant to clause (b), to give information thereof to\nthe Office,\n(d) To review each year the safety and health policy formulated\npursuant to Section 68,\n(e) To perform such other functions as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "75", "title": "Saving from action: No employer shall take disciplinary action against any labour", "content": "for the sole reason that he or she has committed the following act:\n(a) To give information, notice or make or assist in the making of a\ncomplaint against the employer as to failure to make arrangements\non safety and health,\n(b) To do any act in the capacity of a member of the safety and health\ncommittee referred to in Section 74, or\n(c) To stop the work pursuant to Section 76 or 77 because of occurrence\nof an immediate danger to safety and health.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "76", "title": "To stop work in the case of immediate danger: (1) Where it is likely to cause", "content": "bodily injury or risk to, or serious effect on the health of, a labour or other person\nor cause unexpected loss or damage to any equipment, product or material if any\nwork is not stopped immediately, the labour involved in such a work shall give\ninformation thereof to the employer or responsible person referred to in Section\n71.\n(2) The employer or responsible person shall, upon receipt of the\ninformation referred to in sub-section (1), immediately give appropriate direction\nin that respect.\n(3) Where the employer or responsible person is not available for the\ntime being for the purpose of giving information referred to in sub-section (1), the\nlabour himself or herself may stop such a work.\n(4) Where the work is stopped pursuant to sub-section (3), the labour\nwho so stops the work shall immediately give information thereof to the employer\nor responsible person through the fastest means.\n(5) The employer or responsible person shall, upon receipt of the\ninformation referred to in sub-section (4), immediately inquire into the matter and\nprevent or mitigate the risks resulted therefrom.\n30\nwww.lawcommission.gov.np\n(6) Where there arises any dispute between the labour and the employer\nas to whether or not there has arisen any risk necessitating the stoppage of the\nwork and the provision made for the prevention or mitigation of the risk is\nadequate, any party may make an application to the Office for the settlement of\nsuch a dispute.\n(7) On receipt of the application pursuant to sub-section (6), the Office\nshall settle such a dispute upon examining the matter and hearing both the parties,\nand also examining the evidence if so required.\n(8) A decision made for the settlement of such a dispute shall be final\nand both the employer and the labour shall abide by such a decision.\n(9) Notwithstanding anything contained elsewhere in this Section, no\nwork shall be stopped with the intention of causing loss or damage, trouble to or\nsatisfy enmity with the employer.\n(10) During the time when the work remains stopped pursuant to this\nSection, the employer may engage a labour in another work subject to the\nconditions of his or her service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "77", "title": "Direction to stop the work: (1) Where it appears from the inspection or any other", "content": "source that there exists a ground that an immediate danger has arisen or is likely\nto arise in the safety and health of the labour or other person in the workplace of\nany enterprise, the Office may give direction to the employer to immediately stop\nthe work in such a workplace.\n(2) A direction to be issued pursuant to sub-section (1) shall set out,\ninter alia, the reason and ground why such danger has so arisen.\n(3) While issuing the direction pursuant to sub-section (1), the Office\nmay, if it appears that it is not appropriate to operate or use any equipment in the\nworkplace, issue an order forbidding the use of such equipment, and while so\nissuing the order, it may also affix a seal or Tancha on such equipment or any part\nof it.\n(4) If the Office gives direction to stop a work pursuant to sub-section\n(1), the employer shall immediately stop the work.\n(5) The employer who is not satisfied with a direction given by the\nOffice pursuant to this Section may make an application to the Department within\nseven days of the receipt of such a direction.\n31\nwww.lawcommission.gov.np\n(6) The Department shall settle the application made under sub-section\n(5) within fifteen days.\n(7) It is not allowed to do the work during the period referred to in sub-\nsection (6).\nProvided that if the Office gives information during that period that any\nimmediate threat has not arisen to the safety and health of persons, the work may\nbe resumed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "78", "title": "Special provisions relating to occupational safety and health: (1) The safety", "content": "and health standards to be followed by the enterprise engaged in the work related\nto the following matters shall be as prescribed:\n(a) Provisions relating to protection of eyes,\n(b) Provisions relating to protection from chemical substance,\n(c) Provisions relating to operation of pressure plants,\n(d) Provisions relating to safeguard of machines,\n(e) Provisions relating to lifting of load,\n(f) Other necessary provisions.\n(2) Provisions relating to the inspection of pressure plants and boilers\nshall be as prescribed.\n(3) Provisions relating to information about the establishment of any\nenterprise and other provisions relating to occupational safety and health shall be\nas prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "79", "title": "To give information: Where any accident occurs or any person is injured or dies", "content": "in an accident or suffers from any occupational disease in the workplace, the\nemployer shall give information thereof to the Office immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "80", "title": "Arrangements for control of infectious diseases to be made: (1) The employer", "content": "shall make necessary arrangements for the prevention and control of infectious\ndiseases in the workplace.\n(2) If any labour suffering from any infectious disease needs to undergo\ntreatment, he or she may be prevented from attending the work during the period\nof treatment.\n(3) Where the sick leave of such a labour is not sufficient for treatment\npursuant to sub-section (2), the employer may give direction to that labour to make\nadjustment with any other leave or take the special unpaid leave.\n32\nwww.lawcommission.gov.np\n(4) It shall be the duty of the concerned labour to abide by the direction\ngiven pursuant to sub-section (3).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "81", "title": "To engage in easier work: (1) Where any female labour is pregnant, she shall", "content": "give information thereof, accompanied also by a proof showing her health check-\nup, to the employer.\n(2) If the information referred to in sub-section (1) is received, the\nemployer shall generally so engage such a female labour in work that it does not\ncause any adverse effect on her health.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "82", "title": "Special provisions relating to treatment of occupational disease: (1) Where any", "content": "labour suffers from any such occupational disease as prescribed while doing work\nof any enterprise, the enterprise shall provide the labour with such treatment\nexpense as prescribed for the treatment of such a disease and such amount of\ncompensation as prescribed, if such a disease is incurable.\n(2) Notwithstanding anything contained in sub-section (1), the\nenterprise shall not be required to provide the amount of treatment expense or\ncompensation referred to in sub-section (1) if the labour is entitled to the amount\nof expense for the treatment of the occupational disease or compensation from the\nSocial Security Fund.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "83", "title": "Direction may be issued: (1) The Office may make a sudden or periodic", "content": "inspection as to whether or not the employer has made safety and health related\narrangements.\n(2) If, while making inspection pursuant to sub-section (1), it is not\nfound that the employer has made the arrangement on safety and health in the\nworkplace as referred to in this Act or the prevailing law, the Office shall give a\ndirection to the concerned employer specifying the period for making arrangement\nthereof.\nProvided that if it appears that failure to make such arrangement\nimmediately will cause danger to the safety and health of labours or other persons\nor adverse effect on the environment, it shall give direction indicating the matter\nto make such arrangement immediately.\n(3) The Office may give direction to the employer to provide necessary\ninformation and details regarding any accident occurred in the workplace,\noccupational disease or safety and health of labours and other persons.\n33\nwww.lawcommission.gov.np\n(4) It shall be the duty of the concerned employer to abide by or cause\nto be abided by the direction given pursuant to sub-section (2) or (3).", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-13", "title": "Chapter-13", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "84", "title": "Provisions relating to tea-estate labours: (1) The obligations of the employers", "content": "towards the tea-estate labours shall be as follows:\n(a) To make arrangement for suitable quarters within the tea-estate for\nthe labours who do not have their own settlement near the tea-state\nand their dependent family members,\n(b) To make arrangement for free first-aid-service for the treatment of\nminor injuries sustained by the labours and their dependent family\nmembers and for trained medical staff, medical items for that\npurpose,\n(c) To make arrangement for the easy availability of the daily\nconsumable goods if there is no market facility near the tea-estate,\n(d) To make proper arrangement for sports and entertainment for\nphysical and mental development of the tea-estate labours and their\ndependent family members.\nExplanation: For the purpose of this Section, -\n(1) \"Tea estate\" means a tea-estate registered pursuant to the\nprevailing law, and this term also includes a factory, other\nphysical infrastructures established within the tea-estate and\nits premises.\n(2) \"Tea-estate labour\" means a labour who does the work of\ndigging, ploughing, levelling, cutting, plucking, scattering,\nsowing, collecting, uprooting or similar other work in the\nland of a tea estate, and this term also includes a labour who\nis engaged in tea processing and any other work of the tea\nestate.\n(3) \"Dependent family\" means his or her family member who\nlives with a tea-estate labour and whom he or she has to\nmaintain.\n34\nwww.lawcommission.gov.np\n(2) This Section shall not be deemed to bar the making of an agreement\nbetween the labour working in a tea-estate and the employer in relation to any\nwork of the tea-estate to be performed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "85", "title": "Special provisions relating to construction labours: (1) The obligations of the", "content": "employers towards the construction labours shall be as follows:\n(a) To provide such tools, equipment and material in a sufficient\nquantity as may be required for construction,\n(b) To make arrangement for temporary quarters to the labours who do\nnot have settlement near the construction workplace, clean drinking\nwater and supply of necessary food items,\n(c) To make appropriate safety arrangement in the construction\nworkplace.\nExplanation: For the purpose of this Section, -\n(1) \"Construction work\" means the construction of a building,\nroad, bridge, canal, tunnel, internal or inter-state waterway,\nrailway, construction work or construction of a power\nstation, telecommunication, telephone or telegraphic\nstructure and similar other structure, and this term also\nincludes installation of any machine, tool or equipment in\nthat structure.\n(2) \"Construction labour\" means a labour who is engaged in the\nconstruction work.\n(3) Any person or organization who takes responsibility or contract for\nthe construction work shall be deemed to be the employer for the purpose of this\nAct.\n(4) When fixing the rate of remuneration and other benefits for the\nconstruction labours, representation of the trade union of the concerned level and\nof the construction entrepreneurs’ association shall be compulsory.\n(5) Other provisions relating to the construction labours shall be as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "86", "title": "Provisions relating to transport labours: (1) The obligations of the employers", "content": "towards the transport labours shall be as follows:\n35\nwww.lawcommission.gov.np\n(a) To make compulsory provision for at least two drivers to\nrotationally drive any motor vehicle transporting passengers in a\nlong route,\n(b) To make arrangement for taking rest by drivers of any motor vehicle\noperating in a long route in different places before reaching the final\ndestination,\n(c) To provide a transport labour who is employed to work for more\nthan eight hours a day with remuneration at the rate of 1.5 times of\nthe remuneration receivable by the transport labour,\nProvided that if a trip allowance, food allowance or similar\nother allowance is to be provided to the transport labour, he or she\nshall be entitled to only one of such allowance and 1.5 times amount\nthat he or she chooses.\n(d) If the motor vehicle breaks down before reaching the final\ndestination or is required to be stopped in one place for any reason,\nthe labour is to be provided with fifty percent of the allowance\nreceivable by him or her at the time when the motor vehicle is in\nrunning condition,\n(e) To keep in the motor vehicle such medicines and medical treatment\nitems as may be necessary for first-aid treatment.\nExplanation: For the purpose of this Section, -\n(1) \"Long route\" means a long route determined pursuant to the\nlaw.\n(2) “Transportation work” means the transportation by\nmechanical means of passengers, animals or goods from one\nplace to another.\n(3) \"Transport labour\" means any labour engaged in the\ntransportation work.\n(2) No transport labour who drives a motor vehicle shall consume\nalcoholic substance at least twelve hours before driving the vehicle until the final\ndestination is reached.\n(3) A labour who acts contrary to sub-section (2) shall be deemed to\nhave committed a misconduct, and the concerned employer may remove him or\nher from the service.\n36\nwww.lawcommission.gov.np\nProvided that an opportunity to submit explanation shall be provided to\nsuch a labour before so removing him or her from the service.\n(4) If the employer wishes to remove any labour working in a motor\nvehicle in his or her ownership because of a change in ownership effected from\nthe sale of the vehicle or otherwise, the employer may terminate employment\nrelation by providing him or her with such benefits as payable for retirement.\nProvided that this provision shall not apply to an enterprise that operates\nmotor vehicles.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "87", "title": "Special provisions relating to tourism labours: (1) The obligations of the", "content": "employers towards the tourism labours shall be as follows:\n(a) To provide sufficient quantity of medicines and medical treatment\nitems for first aid when sending labours to the workplace,\n(b) To rescue, or cause to be rescued, without delay any labour who gets\nin an accident or serious health problem.\n(2) When sending a labour to the workplace as mentioned in sub-section\n(1), the employer shall provide the labour with any one of such facility out of a\nfield allowance, food allowance or similar other allowance or 1.5 times\nremuneration for overtime work that he or she chooses.\n(3) The employer operating any hotel, motel, restaurant, jungle safari\nor other business shall distribute, as prescribed, the service fees collected pursuant\nto the collective agreement.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "88", "title": "Provisions relating to domestic labours: (1) The Government of Nepal may fix", "content": "separate minimum remuneration for domestic labours.\n(2) Notwithstanding anything contained elsewhere in this Act,\nprovisions relating to public leave, weekly leave of domestic labours and other\nprovisions related thereto shall be as prescribed.\n(3) Where the employer has arranged for food and shelter of a domestic\nlabour in his or her house or assisted in his or her study, the labour may deduct the\namount for such purpose from the remuneration of the labour.\n(4) The employer shall allow a domestic labour to celebrate festivals as\nper his or her culture, religion or tradition.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "89", "title": "Provisions relating to seasonal enterprises: (1) If any seasonal enterprise is", "content": "closed during the off-season, the labours working in such an enterprise shall be\nkept in reserve during the period of its closure.\n37\nwww.lawcommission.gov.np\nExplanation: For the purpose of this Section, the term “seasonal\nenterprise” means an enterprise which can be operated in a particular season only,\nand this term also includes an enterprise which cannot be operated for more than\none hundred eighty days in a year.\n(2) Notwithstanding anything contained elsewhere in this Act, the\nemployer shall provide a labour who is in regular employment with an amount\nequal to twenty-five percent of the remuneration to which he or she is entitled\nduring the period of off-season when the seasonal enterprise remains closed.\n(3) If there arises a question of whether or not any enterprise is a\nseasonal enterprise, it shall be as decided by the Office.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "90", "title": "Provisions relating to enterprise which is incorporated in foreign country and", "content": "operates business in Nepal: If any foreign enterprise involved in the promotion\nof any business or sale of any goods or any other activity in Nepal violates the\nemployment contract entered into with its representative or labour in Nepal, such\na representative or labour may file a complaint to the Office or Labour Court in\naccordance with this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-14", "title": "Chapter-14", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "91", "title": "To observe fair labour practice: The employer, enterprise and trade union shall", "content": "observe fair labour practice in their conduct with each other in the course of their\nrespective activity.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "92", "title": "Deemed to be unfair labour practice: (1) The employer and trade union shall not", "content": "commit, or cause to commit, any unfair labour practice referred to in sub-section\n(2) or (3).\n(2) If any employer does any of the following acts, the employer shall\nbe deemed to have committed the unfair labour practice:\n(a) Not to comply with the labour law or cause such non-compliance,\n(b) To restrict the exercise of any right conferred by the labour law,\n(c) To create knowingly a false evidence with intent to take action\nagainst any labour,\n(d) To commit any act with the sole intention to trouble or harass a\nlabour knowingly,\n38\nwww.lawcommission.gov.np\n(e) To interfere or cause interference in the formation, operation and\nadministrative functions of the trade union,\n(f) To continue the lock-out declared unlawful,\n(g) To assault or manhandle any labour,\n(h) To provoke or incite any labour with an intent to create enmity or\nanimosity among the labours.\n(3) If the trade union commits any of the following acts, it shall be\ndeemed to have committed the unfair labour practice:\n(a) To pressurize or threaten any labour to or not to become a member\nof any union,\n(b) To collect donation or assistance forcibly,\n(c) To picket or surround the employer’s private residence or other\nenterprise except the workplace or causing such picketing or\nsurrounding,\n(d) To assault the employer or his or her representative or any labour or\ndo any other illegal activity in order to have their demand fulfilled\nor causing such assault or activity,\n(e) To commit any act of damaging the employer’s property\nintentionally.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-15", "title": "Chapter-15", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "93", "title": "Provisions relating to Office and inspectors: (1) The Government of Nepal may,", "content": "for the implementation of this Act and prevailing Nepal law on labour, establish\nsuch Labour Offices as may be required.\n(2) The districts which fall within the jurisdiction of the Labour Offices\nestablished pursuant to sub-section (1) shall be as specified by the Ministry.\n(3) The Government of Nepal may, by a notification in the Nepal\nGazette, appoint one inspector or more than one inspectors for any area according\nto the need.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "94", "title": "Powers, functions and duties of the Office: (1) The powers, functions and duties", "content": "of the Office shall be as follows:\n(a) To carry out monitoring as to whether or not the minimum\nremuneration, allowance fixed pursuant to this Act or benefits\n39\nwww.lawcommission.gov.np\nreceivable pursuant to the collective agreement and the rights\nconferred by the prevailing Nepal law to the labours and employers\nhave been implemented,\n(b) To carry out regular monitoring as to whether or not there has been\neffective implementation of this Act and the rules framed under this\nAct, and give necessary direction to the concerned party for their\nimplementation,\n(c) To give trainings on the standards and codes of conduct made\npursuant to this Act and other prevailing labour laws, and carry out\nregular monitoring as to whether or not such standards or codes of\nconduct have been implemented,\n(d) To provide necessary technical assistance to labours and employers\nif such assistance is sought for conducting necessary trainings,\n(e) To give direction to the employer to provide the occupational safety\nand health standards or employee bye-laws rules or other relevant\ndocuments,\n(f) To implement the collective agreement entered into between the\nemployer and labours and arbitral awards,\n(g) To inspect as to whether or not children have been employed, and\nimmediately rescue them if found employed and take action against\nsuch an employer,\n(h) To make inspection as to whether or not the employer has\nimplemented the provisions relating to occupational safety and\nhealth provisions referred to in Chapter-12 in the enterprise and\nworkplace,\n(i) To observe or inspect the machine, tool, equipment, goods or\nmaterial installed in the workplace, and examine whether or not such\nmachine, tool, equipment, goods or material are of prescribed\nstandards, and collect samples thereof if the same needs to be tested,\n(j) To make, or cause to be made, periodic or casual inspection of the\nenterprise or workplace,\n(k) To order the concerned enterprise or its office-bearers to provide\nany register, deed and document including the electronic record\nmaintained in the enterprise or workplace, and take control of the\n40\nwww.lawcommission.gov.np\noriginal register, deed or document or a copy thereof upon entering\nsuch an or workplace in the event of failure to so provide,\n(l) To obtain information or notice on necessary matters from the\nemployer, managerial level labour or other labour of the enterprise,\n(m) If it appears so necessary, to summon the employer, managerial\nlevel labour or other labour of the enterprise to appear in the Office\nand take his or her statement,\n(n) If such information is received during the inspection of the\nworkplace or enterprise or from any other source that the employer\nor labour or trade union has acted contrary to this Act and the rules\nframed under this Act, to give necessary direction to immediately\nrectify such an act,\n(o) To maintain records of the applications or documents received in\nthe Office or information received from any other sources, give\nevidence of the registration of such applications or documents or\nmaintain records of the decisions, orders and deeds of mediation or\nprovide a certified copy of any document to one who requests for\nthe same,\n(p) To perform such other functions as specified by this Act and\nprevailing Nepal law to be performed by the Office, or\n(q) To perform such other functions as may be prescribed.\n(2) The Office may, if it appears necessary to obtain assistance of the\nlocal administration, police or any other body in exercising the power referred to\nin this Section, request the local administration, police or concerned body to render\nsuch assistance.\n(3) It shall be the duty of the local administration, police and concerned\nbody to render such assistance to the Office if so requested pursuant to sub-section\n(2).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "95", "title": "Powers, functions and duties of inspector: (1) Performance of such functions", "content": "and duties and exercise of such powers as to be performed and exercised by the\nOffice shall be made by the inspector and subordinate employee as prescribed.\n(2) Notwithstanding anything contained in sub-section (1), if this Act\nor other law so mentions any function as to be performed by the occupational\nsafety and health inspector himself or herself, the occupational safety and health\n41\nwww.lawcommission.gov.np\ninspector shall have the power to perform for and on behalf of the Office such\nfunction or inspection of the machineries and tools of the factor, occupational\nsafety and health related function and other technical function.\nProvided that nothing contained in this sub-section shall be deemed to bar\nany Office from engaging any occupational safety and health inspector serving in\nanother office or a technician having knowledge in the concerned subject in the\nfunction of inspection and the labour inspector from performing the function\naccordingly, for and on its behalf, if the Office has no occupational safety and\nhealth inspector.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "96", "title": "Obligations of inspector or employee: (1) The obligations of the inspector or", "content": "employee deputed to inspect any enterprise or workplace pursuant to Section 95\nshall be as follows:\n(a) To enter any enterprise or workplace only after showing his or her\nidentity card,\n(b) To give a written receipt thereof while taking custody of any\nregister, document, record or goods,\n(c) To keep the identity of any complainant confidential if he or she\nrequests to do so,\n(d) To perform the duties of his or her office without causing hinderance\nin the work of the enterprise or workplace,\n(e) To keep such notice, information or data as received during\ninspection confidential except as required to be disclosed in\naccordance with the law.\n(2) Where the inspector or any employee who is deputed to inspect any\nenterprise or workplace fails to perform the duties referred to in sub-section (1),\ndoes any act that is disrespectful or contrary to the duties of his or her office or\ncauses any loss or damage by doing any act with mala fide intention, the concerned\nperson shall give information thereof to the competent authority through the\nOffice.\n(3) If the inspector or employee is found guilty upon making necessary\ninquiry pursuant to sub-section (2), the competent authority may take departmental\naction pursuant to the prevailing law.\n42\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "97", "title": "To render necessary assistance: It shall be the duty of the concerned employer,", "content": "labour and trade union to render necessary assistance to the inspector or employee\ndeputed to inspect the enterprise or workplace in the function of inspection.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "98", "title": "Report to be submitted: The inspector or employee shall submit a report setting", "content": "out such particulars as prescribed to the Office within fifteen days from the date\nof completion of the inspection of the enterprise or workplace made pursuant to\nthis Chapter, except as otherwise directed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "99", "title": "Power of the Office to give direction: (1) On receipt of the report pursuant to", "content": "Section 98, the Office may, upon studying it as required, give direction\nimmediately to make the improvement, if any, required to be made in relation to\nany work, working procedure or other matter of the enterprise or workplace or\nlabour or trade union and stop any act, if any, being committed contrary to law.\n(2) A party who is not satisfied with the direction referred to in sub-\nsection (1) may make an appeal to the Labour Court within thirty-five days.\n(3) The decision made by the Labour Court on the appeal made pursuant\nto sub-section (2) shall be final.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "100", "title": "Labour audit to be made: (1) Each enterprise shall make a labour audit as", "content": "prescribed as to whether or not acts and actions are being performed by the\nenterprise in accordance with this Act, Regulation and prevailing law and prepare\na report thereof.\n(2) The report referred to in sub-section (1) shall be provided to the\nOffice or inspector during inspection made pursuant to this Chapter or as and when\nso demanded by the Office or inspector.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "101", "title": "Making application in convenient Office: A labour of any enterprise with its", "content": "branch or workplace in an area where there are more than one Office may make\nan application to the Office which is convenient to him or her, and the concerned\nOffice shall, on receipt of such an application, conduct hearing on the application.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-16", "title": "Chapter-16", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "102", "title": "Formation of Central Labour Advisory Council: (1) There shall be formed a", "content": "Central Labour Advisory Council as follows for giving advice on labour matters\nto the Government of Nepal:\n43\nwww.lawcommission.gov.np\n(a) Minister or Minister of State for Labour and\nEmployment - Chairperson\n(b) Secretary, Ministry of Finance -Member\n(c) Secretary, Ministry of Labour and Employment -Member\n(d) Secretary, Ministry of Physical Infrastructure and -Member\nTransport\n(e) Secretary, Ministry of Agricultural Development -Member\n(f) Secretary, Ministry of Industry -Member\n(g) Secretary, Ministry of Health -Member\n(h) Director General, Department of Labour -Member\n(i) Executive Director, Social Security Fund -Member\n(j) Executive Director, Vocational Skill Development -Member\nTraining Centre\n(k) Five persons including at least two women -Member\nnominated as prescribed by the Ministry from\namongst the employers\n(l) Five persons including at least two women -Member\nnominated as prescribed by the Ministry from\namongst the trade union federations\n(m) Joint Secretary (Responsible for the concerned -Member-\nDivision), Ministry of Labour and Employment Secretary\n(2) The tenure of the members referred to in clauses (k) and (l) of sub-\nsection (1) shall be three years, and they may be re-nominated.\n(3) While nominating the members pursuant to clauses (k) and (l) of\nsub-section (1), the Ministry shall make nomination on the recommendation of the\nemployers’ association, in case of employers, and of the Joint Trade Union\nCoordination Centre, in case of trade union federations.\n(4) The members referred to in clauses (k) and (l) of sub-section (1)\nmay nominate their alternative members to take part, in their absence, in the\nmeetings of the Council.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "103", "title": "Functions, duties and powers of the Council: (1) The functions, duties and", "content": "powers of the Council shall be as follows:\n44\nwww.lawcommission.gov.np\n(a) To give advice and suggestions to the Government of Nepal on\nlabour policies,\n(b) To give necessary advice and suggestions to the Government of\nNepal for making timely reforms in the labour laws,\n(c) To give suggestions to the Government of Nepal in relation to the\nratification and implementation of any labour related international\nconvention to which Nepal is a party,\n(d) To give advice and suggestions to the Government of Nepal in\nrelation to the report to be submitted by the Government of Nepal\nunder any labour related international convention to which Nepal is\na party,\n(e) To prepare occupational safety and health standards and\nrecommend the same to the Government of Nepal,\n(f) To prepare codes of conduct on fair labour practice and recommend\nthe same to the Government of Nepal,\n(g) To give advice and suggestions to the Government of Nepal for the\nformulation of policies concerning vocational training and skill\ndevelopment (apprentice) training,\n(h) To make necessary coordination with the Government of Nepal,\nemployers and trade unions for maintaining industrial peace, sound\nindustrial relation and minimizing labour disputes,\n(i) To make necessary coordination with the Government of Nepal,\nemployers and trade unions for enhancing employment and\nproductivity,\n(j) To frame and issue directives on collective bargaining as required,\nand\n(k) To perform such other functions as prescribed.\n(2) The Council may form any committee or taskforce, as required, for\nthe performance of its functions.\n(3) The functions, duties and powers of the committee or taskforce\nformed pursuant to sub-section (2) shall be as specified by the Council at the time\nof formation of such a committee.\n(4) The secretariat of the Council shall be located in the Ministry.\n45\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "104", "title": "Office of member of the Council to be vacant: (1) The office of any member of", "content": "the Council referred to in clause (k) or (l) of sub-section (1) of Section 102 shall\nbecome vacant in the following circumstance:\n(a) If the member submits resignation in writing to the Ministry through\nthe chairperson,\n(b) If the member remains absent from three consecutive meetings of\nthe Council without giving any notice,\nProvided that this provision shall not apply if the alternative\nmember attends the meeting.\n(c) If his or her tenure expires, or\n(d) If he or she dies.\n(2) Before removing any member of the Council from his or her office\npursuant to clause (b) of sub-section (1), he or she shall be provided with an\nopportunity to defend.\n(3) Where the office of any member falls vacant pursuant to sub-section\n(1), nomination of another person shall be made for the remainder of tenure from\nthe same sector where that member was nominated from and by following the same\nprocedure.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "105", "title": "Provisions relating to meetings of the Council: (1) Meetings of the Council shall", "content": "be held as required at the date, place and time specified by the chairperson of the\nCouncil.\nProvided that the interval between the two meetings shall not be more than\nfour months.\n(2) The chairperson shall call a meeting within fifteen days if one fourth\nof the total number of members of the Council makes a written request for calling\na meeting.\n(3) The member-secretary of the Council shall give a notice along with\nthe agenda of the meeting to all the members at least twenty-four hours in advance\nof the time when such meeting is scheduled.\n(4) The presence of more than at least fifty percent of the total number\nof members, representing the Government of Nepal, employers and trade unions,\nshall constitute a quorum for the meeting of the Council.\n46\nwww.lawcommission.gov.np\n(5) The chairperson of the Council shall preside over the meeting of the\nCouncil, and in his or her absence, the secretary of the Ministry shall preside it\nover.\n(6) A labour expert may be invited at the meeting of the Council.\n(7) Any decision of the Council shall be taken on the basis of consensus.\n(8) If consensus is not reached pursuant to sub-section (7), a decision\nshall be taken on the basis of majority of the members representing the\nGovernment of Nepal, employers and unions.\n(9) There shall be maintained a separate minute book for recording the\ndecisions of the meetings of the Council, and such decisions shall be authenticated\nby the member-secretary of the Council.\n(10) Other procedures relating to the meeting of the Council shall be as\ndetermined by the Council itself.\n(11) Members of the Council shall get such meeting allowance as\nspecified by the Government of Nepal.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "106", "title": "Fixation of minimum remuneration: (1) The Ministry shall, on recommendation", "content": "of the Minimum Remuneration Fixation Committee referred to in Section 107, fix\nthe minimum remuneration of labours in every two years.\n(2) Notwithstanding anything contained in sub-section (1), the Ministry\nmay fix the minimum remuneration in the event of failure of the Minimum Wage\nFixation Committee referred to in Section 107 to recommend the minimum\nremuneration due to absence of consensus.\n(3) The Ministry shall publish the minimum remuneration fixed\npursuant to this Section in the Nepal Gazette.\n(4) The minimum remuneration fixed pursuant to sub-section (3) shall\ncome into force on the first day of the new financial year.\nProvided that if it is otherwise agreed between the trade union and the\nemployer concerning the date of coming into force of the minimum remuneration,\nit shall come into force accordingly.\n(5) When fixing the minimum remuneration in accordance with other\nprevailing law, such remuneration shall not be so fixed as to be less than the\nremuneration fixed pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "107", "title": "Minimum remuneration fixation committee: (1) The Ministry shall form a", "content": "permanent minimum remuneration fixation committee as prescribed, consisting of\n47\nwww.lawcommission.gov.np\nrepresentatives from the Government of Nepal, trade unions and employers'\nassociations for the purpose of recommending the minimum remuneration of\nlabours.\n(2) The committee formed pursuant to sub-section (1) may, while\nrecommending the minimum remuneration of labours, recommend the minimum\nremuneration of labours applicable for the whole of Nepal or for enterprises or\nindustries of any specific sector or nature or specific sector of employment.\n(3) The grounds for recommendation of the minimum remuneration\nshall be determined by the minimum remuneration fixation committee itself\nreferred to in sub-section (1).\n(4) The minimum remuneration fixation committee referred to in sub-\nsection (1) shall commence the process of reviewing the minimum remuneration\nfrom the month of Baishak (mid April) in every two years.\n(5) Procedures and other provisions relating to the meetings of the\ncommittee referred to in sub-section (1) shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-17", "title": "Chapter-17", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "108", "title": "Internal management may be made: (1) Every enterprise may, for the purpose", "content": "of its internal management, make a bye-law as required.\n(2) Any enterprise, when making a bye-law on service, conditions and\nbenefits of labours, or any competent body to approve the bye-law made by any\nenterprise, when approving such a bye-law, shall do so make or approve as not to\nbe contrary to the minimum standards set forth in this Act and the collective\nagreement.\n(3) The Ministry may, for the purpose of sub-section (1), make a model\nbye-law as required.\nProvided that it shall not be deemed to bar the Nepal Rastra Bank, in the\ncase of banks and financial institutions, and the regulatory authority, in the case\nof other enterprises, from making bye-laws.\n(4) One copy of the bye-law made by an enterprise shall be registered\nin the Office, such a bye-law shall be made available to any labour if he or she\nwishes to look at.\n48\nwww.lawcommission.gov.np\n(5) The enterprise shall, when making or amending the bye-law, consult\nthe authorised trade union, if any, in the enterprise and an active trade union if\nthere is no such authorized trade union.\n(6) Where any provision of the bye-law made by the enterprise\ncontradicts with this Act, prevailing laws or collective agreement, the court may\nvoid such a provision of the bye-law or give other appropriate order.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "109", "title": "Transfer may be made: (1) The enterprise may transfer a labour from one office,", "content": "branch or unit of the enterprise to another office, branch or unit without causing\nany adverse effect on the conditions of service and benefits of him or her and\nwithout making difference in the nature and level of his or her work.\n(2) Provided that transfer may be made in a manner to make difference\nin the nature and level of work in the following circumstance:\n(a) With the consent of the concerned labour,\n(b) Where the labour is promoted and placed,\n(c) As mentioned in the collective agreement, or\n(d) To transfer the labour to other work related to the training or skill\nor educational qualification acquired by him or her.\n(2) Any labour employed in any one enterprise may, with his or her\nconsent, be transferred to another enterprise.\n(3) When making transfer pursuant to sub-section (2), an agreement\nshall be made as prescribed between the enterprise making transfer and the\nenterprise where the labour is transferred to on the matter that the service period\nof the employee to be so transferred shall be added and the enterprise where the\nlabour is transferred to shall bear all benefits to the receivable on the basis of the\nservice period and on other conditions of service.\n(4) When transferring any labour from the workplace located in the\nplace of his or her permanent residence or to any other place from the existing\nworkplace, the employer shall provide benefits as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "110", "title": "To be deputed as representative: (1) Any enterprise may depute its labour to", "content": "another enterprise to work in the capacity of its representative.\n(2) Except as otherwise agreed when making deputation pursuant to\nsub-section (1), the obligations relating to the service and benefits of such a labour\nshall be vested in the enterprise making such deputation.\n49\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "111", "title": "Formation of labour relation committee: (1) The employer of an enterprise", "content": "where ten or more than ten labours work shall form a labour relation committee as\nprescribed.\n(2) The functions, duties and powers of the committee formed pursuant\nto sub-section (1) shall be as follows:\n(a) To hold discussion as required for productivity increment\nand improvement in the operating system,\n(b) To make an effort to settle any grievance in discussion with\nthe concerned party if the labour has or is likely to have such\na grievance,\n(c) To improve the working environment of the workplace,\n(d) To function in the capacity of occupational safety and health\ncommittee until it is formed, and\n(e) To perform such other functions as prescribed.\n(3) The labour relation committee referred to in sub-section (1) shall\nmeet as required without adversely affecting the working hours of the enterprise.\n(4) Provisions relating to the formation, procedure and meeting of the\ncommittee shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "112", "title": "Performance evaluation of labours by enterprise: (1) An enterprise may have", "content": "performance evaluation of its labours generally once in a year.\n(2) The basis and procedure for the performance evaluation referred to\nin sub-section (1) shall be determined in a just and reasonable manner.\n(3) The basis and procedure referred to in sub-section (2) shall be\nnotified to the labours before the period for the performance evaluation\ncommences.\n(4) Upon completion of the performance evaluation pursuant to sub-\nsection (1), the employer or the person designated by him or her shall discuss with\nthe concerned labour about his or her strengths and weaknesses and give a\nreasonable opportunity to improve the weaknesses.\n(5) Where the concerned labour disagrees with the evaluation made\npursuant to sub-section (4), such a labour shall be required to sign the evaluation\nform after providing him or her with an opportunity to note down disagreement.\n(6) Where a labour notes down disagreement pursuant to sub-section\n(5), the enterprise shall make a provision for its review.\n50\nwww.lawcommission.gov.np\n(7) Other provisions relating to the performance evaluation of the\nlabours shall be as prescribed.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-18", "title": "Chapter-18", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "113", "title": "Submission of individual claims: (1) If any labour has an individual claim on any", "content": "matter related to the right conferred by this Act, Regulation, prevailing laws or\ncollective agreement, such a labour may make an application in writing to the\nemployer.\n(2) In the event of receipt of the application referred to in sub-section\n(1), the employer shall receive the application and give its receipt to the labour.\n(3) In the event of receipt of the application referred to in sub-section\n(1), the employer shall settle the dispute relating to such a claim within fifteen\ndays upon holding discussion with the concerned labour.\n(4) Notwithstanding anything contained in sub-section (3), the period\nfor the settlement of dispute may be extended through consent between the\nemployer and the labour.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "114", "title": "Application may be made to the Office: (1) The concerned party may, in the", "content": "following circumstance, make an application to the Office for the settlement by\nmediation of the individual claim referred to in Section 113:\n(a) If the employer does not give a notice for discussion within seven\ndays from the date on which the application was made pursuant to\nsub-section (1) of Section 113, or\n(b) Failing an agreement upon discussion held pursuant to sub-section\n(3) of Section 113, after fifteen days from the date on which the\noriginal application was made to the employer.\n(2) In the event of receipt of the application pursuant to sub-section (1),\nthe Office shall give the concerned employer and the labour a notice specifying\nthe date and time for discussion.\n(3) The Office shall settle the dispute relating to the claim within\ntwenty-one days from the date of receipt of the application pursuant to sub section\n(1), by holding negotiations as required between the employer and the labour.\n51\nwww.lawcommission.gov.np\n(4) Notwithstanding anything contained in sub-section (3), the period\nfor the settlement of dispute may be extended through consent between the Office,\nemployer and labour.\n(5) If an agreement is reached between the concerned employer and the\nlabour upon the negotiations referred to in sub-section (3), such a dispute relating\nto the claim shall be deemed to have been settled.\n(6) The agreement reached pursuant to sub-section (5) shall be binding\non the concerned party.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "115", "title": "Decision to be made by the Office: Where the problem could not be solved", "content": "pursuant to Section 114, the Office shall, on the basis of the available evidence,\nmake a decision within fifteen days.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-19", "title": "Chapter-19", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "116", "title": "Collective claim may be submitted: (1) Any enterprise employing ten or more", "content": "than ten labours shall have a collective bargaining committee as follows:\n(a) A team of negotiating representatives designated on behalf of the\nelected authorized trade union of the enterprise,\n(b) In cases where election to the authorised trade union referred to in\nclause (a) could not be held or where election has been held but its\nterm has expired, a team of negotiating representatives nominated\nthrough mutual agreement of all the unions in the enterprise,\n(c) In cases where there is no authorised trade union referred to in\nclause (a) or team referred to in clause (b), a team of representatives\nsupported with the signatures of more than sixty percent of the\nlabours working in the enterprise.\n(2) The collective bargaining committee may submit collective claims\nor demands in writing to the employer on issues relating to the interest of the\nlabours.\n(3) Notwithstanding anything contained in sub-section (2), no\ncollective claims or demands may be submitted on the following matters:\n(a) A matter which is contrary to the Constitution of Nepal,\n(b) A matter which contains an allegation with no evidence or basis and\nis thus contrary to the interest of any one,\n52\nwww.lawcommission.gov.np\n(c) A matter which affects the personal conduct of any employer or\nlabour,\n(d) A matter which is not related to the enterprise,\n(e) Until the period specified in this Act lapses in cases where the\ncollective agreement has been made,\n(f) A matter relating to the rate of contribution and benefits specified\nfor the social security scheme.\n(4) The collective bargaining committee may consist of a maximum of\nthree to eleven members as prescribed, on the basis of the number of labours.\n(5) The collective bargaining committee formed pursuant to this\nSection shall have the powers including that to submit collective claims or\ndemands, enter into agreement, file a case against any person or defend a case.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "117", "title": "To hold negotiations on collective claims, demands: (1) In the event of", "content": "submission of collective claims, demands pursuant to Section 116, the concerned\nemployer shall, not later than seven days of the date of submission of such claims\nor demands, give a notice in writing to the collective bargaining committee, stating\ninter alia the venue and time for negotiation.\n(2) Where a notice is given pursuant to sub-section (1), the members of\nthe collective bargaining committee shall be present for negotiations at the venue\nand time stated in the notice.\n(3) If, while conducting negotiations, any understanding or agreement\nis reached between both the parties, the disputes relating to the collective claims,\ndemands shall be settled.\n(4) The understanding or agreement made pursuant to sub-section (3)\nshall be binding for the concerned parties.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "118", "title": "Settlement through mediation: (1) The concerned party may, in the following", "content": "circumstance, make an application to the Office for the settlement of collective\nclaims, demands through mediation:\n(a) Where the employer fails to give a notice to the collective\nbargaining committee for negotiations within the period referred to\nin sub-section (1) of Section 117, or\n(b) Where an agreement could not be reached upon negotiation held\npursuant to sub-section (3) of Section 117 not later than twenty-one\ndays from the date of submission of claims, demands.\n53\nwww.lawcommission.gov.np\nProvided that nothing shall be deemed to bar the extending\nof the said period with the consent of the parties in cases where the\nnegotiation is going on.\n(2) In the event of receipt of an application pursuant to sub-section (1),\nthe Office shall summon the presence of the concerned parties and settle the\ndispute through mediation.\n(3) The mediation proceeding referred to in sub-section (2) shall be\ncompleted not later than thirty days from the date of receipt by the Office of the\napplication.\nProvided that nothing shall be deemed to bar the extending of the said\nperiod with the consent of the parties in cases where the negotiation is going on.\n(4) The dispute relating to the collective claims, demands shall be\nsettled if an agreement is reached between both the parties upon the negotiation\nheld in presence of the Office pursuant to sub-section (3).\n(5) The agreement made pursuant to sub-section (4) shall be binding for\nthe concerned parties.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "119", "title": "Settlement of dispute through arbitration: (1) Where mediation does not", "content": "succeed pursuant to Section 118, the dispute relating to the collective claims,\ndemands shall, in the following circumstance, be settled through arbitration:\n(a) If the collective bargaining committee and the employer agree to\nsettle the dispute relating to collective claims, demands through\narbitration,\n(b) If a collective dispute arises in an enterprise providing essential\nservices,\n(c) If a collective dispute arises in an enterprise within the special\neconomic zone, or\n(d) If the strike is prohibited by imposition of a state of emergency in\naccordance with the Constitution.\nExplanation: For the purpose of this Chapter, the term “essential\nservice” means any service which may, if interrupted, have an\nadverse impact on the life, health and safety of the people across the\ncountry or the people living in any part of the country.\n(2) Where the Ministry has a ground to believe that a financial crisis\nmay arise in the country as a result of ongoing or possible strike or lockout or that\n54\nwww.lawcommission.gov.np\nthe dispute needs to be settled by arbitration, the Ministry may give an order for\nthe settlement of any collective dispute through arbitration irrespective of the stage\nof such a dispute.\n(3) For the purpose of sub-sections (1) and (2), the Ministry may form\nan arbitration panel comprising representations from the labour, employer and\nGovernment of Nepal.\n(4) Expenses of the arbitration panel to be formed pursuant to sub-\nsection (3) shall be borne by the Government of Nepal as prescribed.\n(5) Any party wishing to have the dispute settled through arbitration\nshall submit claims in writing to the arbitrator as prescribed.\n(6) On receipt of the claims referred to in sub-section (5), the arbitrator\nshall send a copy of such claims to the other party and provide an opportunity to\nsuch party to submit counter-claims in that respect.\n(7) In conducting the proceeding referred to in this Section, the\narbitrator may consult or discuss with any expert.\n(8) Hearing shall be conducted at such date, time and place specified by\nthe arbitrator, and the arbitration proceeding shall not sojourn for the sole reason\nthat any party has remained absent or counter-claim has not been submitted.\n(9) The arbitrator shall make award not later than thirty days from the\ndate of completion of the hearing pursuant to sub-section (8).\n(10) The arbitrator may exercise such powers as the court has under the\nprevailing laws in relation to the matters including examining the evidence, taking\ndepositions of witnesses, making on-site inspections, in connection with the\nproceeding.\n(11) Except as otherwise provided for in the agreement by the parties,\nother provisions relating to the arbitral proceeding shall be as determined by the\narbitrator.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "120", "title": "Power to form labour arbitration tribunal: (1) The Government of Nepal may", "content": "form an independent labour arbitration tribunal for having mediation and\narbitration with regard to the collective dispute.\n(2) Where a labour arbitration tribunal is formed pursuant to sub-\nsection (1), the labour arbitration tribunal shall conduct the mediation and\narbitration proceedings referred to in this Chapter.\n55\nwww.lawcommission.gov.np\n(3) Other provisions relating to the labour arbitration tribunal shall be\nas prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "121", "title": "Right to strike for settlement of collective disputes: (1) The collective", "content": "bargaining committee may, if any of the following circumstances exists, organize\na strike for the settlement of any collective dispute:\n(a) If there exists no circumstance requiring compulsory arbitration\npursuant to sub-section (1) of Section 119,\n(b) If the arbitrator fails to perform the arbitral functions,\n(c) If an arbitration panel could not be formed within twenty-one days\nfrom the date of application to the Ministry or decision is not made\nrequiring arbitration,\n(d) If award is not given by the arbitrator within the prescribed time,\n(e) If the employer refuses to enforce the arbitral award or challenges\nsuch an award on legal grounds,\n(f) If, except where compulsory arbitration is to be made, any party\ndisagrees with the arbitral award pursuant to sub-section (2) of\nSection 122.\n(2) In order to make a strike pursuant to sub-section (1), a written notice\nalong with the claims, demands, and also specifying the date from which the strike\nis to commence shall be submitted to the employer in advance of thirty days, and\ninformation thereof shall also be given to the local administration and the\nconcerned Labour Office.\n(3) Notwithstanding anything contained elsewhere in this Act, if the\nMinistry gives an order for the settlement of the dispute through arbitration\npursuant to sub-section (2) of Section 119 after the notice on strike is given or the\nstrike is commenced pursuant to sub-section (2), they shall postpone such a strike\nand participate in the arbitral process.\n(4) Notwithstanding anything contained elsewhere in this Act, the\nlabours deputed as sentries and guards for the security of the enterprise shall not\nbe allowed to participate in the strike and do any act referred to in Section 125\nduring the time when they are assigned on duty.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "122", "title": "Arbitral award and collective agreement to be binding: (1) If any collective", "content": "dispute is settled through compulsory arbitration pursuant to sub-section (1) of\nSection 119, the arbitral award shall be binding on the concerned parties.\n56\nwww.lawcommission.gov.np\n(2) If any party to any dispute referred to arbitration in pursuance of the\norder by the Ministry pursuant to sub-section (2) of Section 119 who is not\nsatisfied with the arbitral award on the dispute fails to node down disagreement in\nwriting to the arbitrator not later than five working days from the date of the award,\nsuch an award shall also ipso facto be binding on the concerned party after the\nexpiration of that period.\n(3) The collective agreement and arbitral award need to be registered in\nthe Office for record and enforcement thereof.\n(4) The collective agreement shall remain valid for two years from the\ndate of its entry into force, if any, specified in the agreement itself and, failing the\nspecification of such a date, from the date of signing of the agreement and from\nthe date of the arbitral award, if any, made, and shall be valid as of law.\n(5) Notwithstanding anything contained in sub-section (4), the\nprovisions in the collective agreement or arbitral award shall continue to apply\nunless and until it is amended or repealed by another collective agreement or\narbitral award.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "123", "title": "Special provisions relating to the submission of collective claims, demands:", "content": "(1) Trade union associations which are active in the tea estate, carpet sector,\nconstruction business, labour provider, transportation sector or any other group of\nmanufacturers producing similar nature of goods or service providers providing\nsimilar nature of service or business as prescribed may form a collective\nbargaining committee as prescribed and submit collective bargaining claims,\ndemands to the employers' association of the concerned group of industries.\n(2) The manner of submitting claims, demands referred to in sub-\nsection (1), procedure relating to collective bargaining and provisions relating to\nthe agreement shall be as prescribed.\n(3) In the case of the enterprise to which the collective agreement\nreferred to in this Section is applicable, no collective claims, demands and\nagreement may be submitted and made pursuant to this Chapter.\n(4) Notwithstanding anything contained in sub-section (4) of Section\n122, the Ministry may issue an order that collective claims, demands and\nnegotiations should be submitted and held within a specified time. In the event of\nissuance of such an order, it may happen earlier or later than the time specified in\nthe same sub-section of the same Section.\n57\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "124", "title": "Right to lock-outs: (1) Where a strike is organized or continued without giving a", "content": "notice pursuant to this Act or the collective dispute could not be settled through\nthe procedure referred to in this Act, the management may, by giving justifiable\ngrounds, lock out the enterprise by obtaining approval of the Department.\n(2) Before making a lock-out pursuant to sub-section (1), the manager\nshall issue a notice in advance of at least seven days, also specifying the date of\nlock-out, for information to the labours that if the strike is not ended the lock-out\nwill be made.\n(3) Notwithstanding anything contained in sub-sections (1) and (2),\nwhere there is a possibility of causing loss to the enterprise because of gherao,\nriot, physical unrest etc. by the labours during the period of strike, the management\nmay lock out the enterprise. If the lock-out is so made, information along with the\njustification for making such lock-out shall be given to the Office or Department\nand the local administration not later than three days.\n(4) On receipt of the notice pursuant to sub-section (3), the local\nadministration shall immediately make necessary security arrangement in such a\nworkplace.\n(5) The Department may at any time declare the lock-out of any\nenterprise illegal in case it appears to be unjustifiable or it is likely to disturb the\npeace and security of the country or it is contrary to the economic interest of the\ncountry.\n(6) Notwithstanding anything contained elsewhere in this Section, no\nlock-out may be made in an enterprise that operates any essential service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "125", "title": "Picketing or assembly may be made: (1) With the objective of exerting pressure", "content": "to have fulfilled the demands when the strike or lock-out is continuing, the labours\nmay picket or assemble at the main entrance of the workplace or enterprise\npeacefully.\n(2) In any circumstance other than the circumstance where strike or\nlockout, they may picket or assemble before or after the working hours or during\nthe rest time without disturbing the work of the workplace or enterprise.\n(3) Even in cases where picketing or assembly is made pursuant to sub-\nsection (1), the labours may not do any act and action such as prohibiting others\nfrom entering or leaving the workplace or enterprise or causing any loss or damage\nto the workplace.\n58\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "126", "title": "Employment contract not to be violated: No labour shall be deemed to have", "content": "violated the employment contract by the reason that he or she has made a strike,\nlock-out or picketing or made a complaint in accordance with the law, and during\nthat period, the employment contract shall be deemed to continue to be effective.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "127", "title": "Remuneration for strike or lock-out period: (1) Any labour who makes a strike", "content": "in a manner to be contrary to the prevailing law shall not be entitled to any\nremuneration for the period of such a strike.\n(2) Labours shall be entitled to full remuneration for the period of lock-\nout if such lock-out is made by the employer in a manner to be contrary to the\nprevailing law.\n(3) If the collective agreement contains any agreement in relation to the\nremuneration, the matter shall be governed accordingly; and failing such\nagreement to that effect, the labour shall get half the remuneration for the period\nof strike or lock-out made in fulfilment of the procedure of this Act.\n(4) If there arises any dispute as to whether any strike or lockout made\nin an enterprise is contrary to law or not, the Department shall conduct necessary\ninquiry and make decision not later than thirty-five days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "128", "title": "Prohibition on filing of case against loss: (1) Where any financial loss is caused", "content": "to the employer or labour because of a strike, picketing or lock-out made in\nfulfilment of the procedures referred to in this Act, no case may be filed in any\ncourt against any labour, collective bargaining committee, trade union or employer\ninvolved in such a strike, picketing or lock-out in relation to such a loss.\n(2) Notwithstanding anything contained in sub-section (1), if any\nperson or group makes destruction or arson in the workplace or destruction of any\nproperty in any other manner or causes physical damage, the amount equivalent to\nthe loss, damage may be recovered from such a person or group.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "129", "title": "Collective bargaining or agreement to be made in good faith: (1) The trade", "content": "union or collective bargaining committee or employer shall, in making a collective\nbargaining or collective agreement, do so in good faith.\n(2) Other provisions relating to the collective bargaining or agreement\nshall be as prescribed.\n59\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-20", "title": "Chapter-20", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "130", "title": "Observance of discipline and duties: It shall be the duty of each labour to", "content": "observe discipline and fulfil duties referred to in this Act or the rules framed under\nthis Act or the by-law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "131", "title": "Misconduct and punishment: (1) If a labour commits the following misconduct,", "content": "he or she may be reprimanded:\n(a) To remain absent from the work without having a leave sanctioned,\n(b) To leave the workplace without obtaining permission of the\nmanagement,\n(c) To appear late in work frequently without obtaining permission,\n(d) To disobey any order given in relation to the work by the employer\nor any employee superior in level to him or her,\n(e) To commit such other misconduct as specified in the bye-law.\n(2) In the event of commission of any of the following misconducts,\nremuneration equal to a maximum of one day may be deducted:\n(a) To refuse to receive any letter or notice given by the employer or\nsentencing authority,\n(b) To take part in an illegal strike or force others to do so or make delay\nor slow in work collectively,\n(c) To cause loss or damage to the enterprise by decreasing the\nproduction or service recklessly or negligently,\n(d) To make attempt to take benefits by submitting false documents,\n(e) To not use the equipment provided by the employer if he or she is a\nlabour responsible for using such equipment,\n(f) To commit such other misconduct of similar nature as specified in\nthe bye-law.\n(3) In the event of commission of any of the following misconducts,\nannual salary increment of one year may be withheld or promotion withheld for\none year:\n(a) To take any property outside the enterprise without the permission\nof the competent person and use it or allow it to be used by any\nunauthorized person,\n60\nwww.lawcommission.gov.np\n(b) To make attempt to make embezzlement in the employer’s\ntransaction,\n(c) To damage the employer’s property recklessly or negligently,\n(d) To stop the supply of food, water, telephone, electricity service or\nprevent movement within the workplace,\n(e) To intentionally misuse, or cause loss or damage to any goods kept\nor provisions made for the benefit, safety or health of the labours,\n(f) To commit such other misconduct of similar nature as specified in\nthe by-law.\n(4) A labour may be dismissed from the service if he or she commits\nany of the following misconducts:\n(a) To batter or cause bodily injury to, or take hostage the employer,\nany labour, customer or any person concerned with the workplace\nwith or without the use of arms or weapon, or cause unrest or\ndestruction in the area of the enterprise,\n(b) To take or give a bribe,\n(c) To steal any one’s property in the workplace,\n(d) To make financial misappropriation in the enterprise,\n(e) To intentionally cause damage to any property that belongs to or is\nin the custody or use of the employer,\n(f) To remain absent from the work for more than thirty consecutive\ndays without having a leave sanctioned,\n(g) To do any act of divulging secrecy of any production technology\nrelated formula or confidential information of the enterprise or\nworkplace where he or she is working with the intention of causing\nloss or damage to such an enterprise,\n(h) To act in collaboration with a competitive employer in the similar\nnature of business of the enterprise or carry on any competitive\nbusiness on his or her own or provide any secret information of the\nenterprise where he or she is employed to any competitive employer,\n(i) To get convicted by the court of any criminal offense involving\nmoral turpitude during the period of employment,\n(j) To make and submit any fake educational certificate and other\ncertificate for the purpose of appointment,\n61\nwww.lawcommission.gov.np\n(k) To consume narcotic substance or liquor during the working hours\nor come to the workplace upon consuming the same,\n(l) To get punished for more than two times for the misconduct\npursuant to sub-sections (1), (2) and (3) within a period of three\nyears,\n(m) To commit any misconduct if the prevailing law provides for the\ndismissal from service in the case of commission of such\nmisconduct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "132", "title": "Prohibition of sexual harassment: (1) No person shall commit, or cause to be", "content": "committed, any such act, with the exertion of undue influence, as considered to be\nsexual harassment under the law in the workplace or in the course of work.\n(2) The employer may, depending on the condition and gravity of the\nact, impose punishment to the extent of even dismissal from the service on the\nlabour who commits sexual harassment.\n(3) Where the employer or chief executive of any enterprise commits\nsexual harassment, the trade union, victim or any member of his or her family may\nfile a complaint in accordance with the law.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "133", "title": "Provisions relating to misconduct may be made in the bye-law: (1) Where", "content": "specific punishment for specific type of misconduct has been prescribed by the\nrespective regulatory bodies regulating banks or financial institutions, schools,\ntelecom service providers, hospitals, air services, insurance services or enterprises\nof specific nature, provisions may be made in the bye-laws accordingly.\n(2) Provisions may be made in the bye-law of an enterprise for dismissal\nfrom the service as per the collective agreement or with the approval of the\nDepartment in the event of commission of misconduct of a serious nature.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "134", "title": "Power to suspend: (1) Where any labour is detained in accordance with law, such", "content": "a labour shall ipso facto be suspended during that period and shall not be entitled\nto remuneration for that period.\nProvided that if a labour who is detained upon a complaint filed by the\nemployer himself or herself is proved to be innocent, he or she shall be entitled to\nthe full remuneration for that period.\n(2) Except in the cases referred to in sub-section (1), if it does not\nappear appropriate to keep on engaging in work a labour for whom the punishment\nreferred to in sub-section (4) of Section 131 has been proposed or if there is a\n62\nwww.lawcommission.gov.np\npossibility that he or she may destroy the evidence relating to the charge made\nagainst him or her or obstruct the investigation, the employer may suspend such a\nlabour.\n(3) While suspending any labour pursuant to sub-section (2), he or she\nmay not be suspended generally for more than three months.\nProvided that the period of suspension may be extended by a maximum of\none month if the investigation is not completed.\n(4) The labour shall be entitled to half the remuneration during the\nperiod of suspension referred to in sub-section (2).\n(5) Where a labour who has been suspended pursuant to sub-section (2)\nis acquitted of the allegation made against him or her, he or she shall be entitled\nto all such remuneration, and increment in salary if any, receivable by him or her\nthat remains after deducting the amount of remuneration which he or she has\nreceived during the period of suspension.\n(6) Except where any labour is held in detention upon first information\nreport or complaint by the employer himself or herself, the employer may\nterminate the service of such a labour if the period of suspension referred to in\nsub-section (1) exceeds ninety days. The opportunity hearing need not be given to\nthe concerned labour while so terminating the service.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "135", "title": "Opportunity to be given to submit clarification: Prior to imposing punishment", "content": "on any labour for misconduct, the authority imposing punishment shall provide\nsuch a labour with a notice giving opportunity to submit clarification within a\nperiod of seven days, and such a notice shall clearly state also the facts of\ncommission of the misconduct and possible punishment imposable if it is proved.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "136", "title": "Authority imposing punishment: (1) The power to impose punishment for", "content": "misconduct shall be vested in its chief executive in the case of an enterprise.\n(2) Notwithstanding anything contained in sub-section (1), if the bye-\nlaw empowers any managerial level labour to take final decision concerning the\npunishment imposable for any misconduct, such an authority shall have power to\ninvestigate and impose punishment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "137", "title": "Period for taking decision: (1) Where any labour is found to have committed", "content": "misconduct, it is necessary to commence action within two months from the date\nof knowledge of the commission of such misconduct.\n63\nwww.lawcommission.gov.np\n(2) A decision shall be taken within three months from the date of\ncommencement of the action pursuant to sub-section (1).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "138", "title": "Punishment may be remitted: (1) Nothing contained in this Chapter shall be", "content": "deemed to bar the imposing of lesser punishment on any labour by proposing\nhigher punishment.\n(2) Where any enterprise has made a bye-law providing for lesser\npunishment than that imposable under this Chapter, the provision of the bye-law\nshall apply to the labours of such an enterprise.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-21", "title": "Chapter-21", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "139", "title": "Security of employment: (1) Employment of any labour shall not be terminated", "content": "in any condition except in accordance with this Act and the rules or bye-law\nframed under this Act.\n(2) Proper and sufficient reason shall be given when terminating the\nemployment.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "140", "title": "Termination of time-based and work-based employment: Employment of a", "content": "labour engaged in a time-based or work-based employment shall be terminated in\nthe following circumstance:\n(a) After the expiry of the time specified in the employment contract,\nin the case of the labour engaged in the time-based employment,\nProvided that if the labour is in project-based employment\nand the period is extended or the period for the completion of such\na work is extended on the basis of the nature of the work, the\nemployment shall not terminate until that period.\n(b) After the completion of the work specified in the employment\ncontract in the case of a labour who is in work-based employment,\nor\nProvided that if the labour is in project-based employment\nand the work is added or the period for the completion of such a\nwork is extended on the basis of the nature of the work, the\nemployment shall not terminate until that work remains.\n(c) In the case of a labour in casual employment, at the will of the\nemployer or labour.\n64\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "141", "title": "Employment may be terminated voluntarily: (1) Any labour may, by submitting", "content": "resignation in writing to the employer, terminate the employment.\n(2) The employer shall accept the resignation submitted pursuant to\nsub-section (1) within fifteen days and give information thereof to the labour.\n(3) Where the employer does not accept the resignation within the time-\nlimit referred to in sub-section (2), such resignation shall be deemed to have been\naccepted ipso facto from the day following the day on which the time-limit expires.\n(4) Notwithstanding anything contained elsewhere in this Section, the\nresignation submitted by a labour may be cancelled through mutual consent\nbetween the employer and the labour.\n(5) If the labour continues working in the same enterprise even after the\nday on which his or her resignation is accepted and becomes effective, his or her\nresignation shall be deemed to have been cancelled.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "142", "title": "Employment may be terminated on the ground of incompetence: (1) If, while", "content": "evaluating the work performance of any labour pursuant to the provisions set forth\nin this Act or the rules and bye-law framed under this Act, the work performance\nof such a labour is found unsatisfactory or poor for three or more than three\nconsecutive years, the employer may terminate the employment of such a labour.\n(2) Prior to terminating the employment pursuant to sub-section (1), the\nwork performance evaluation must have been made as set forth in this Act or the\nrules and bye-law framed under this Act.\n(3) Prior to terminating the employment of any labour pursuant to this\nSection, the employer of any enterprise employing ten or more labours shall give\na period of at least seven days to the concerned labour for clarification.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "143", "title": "Employment may be terminated on the ground of health: (1) Where any labour", "content": "becomes incapable of working as a result of physical or mental incapacitation or\ngrievous hurt or injury or it affects the work because of a long time required for\nmedical treatment, the employer may, on the basis of recommendation by a\nmedical doctor, terminate the employment of such a labour.\n(2) Notwithstanding anything contained in sub-section (1), the\nemployment of any labour may not be terminated during the period he or she is\nundergoing treatment in a hospital because of any accident or occupational disease\nwhile performing the work specified by the employer or until one year from the\ndate of commencement of his or her treatment at home if he or she is undergoing\n65\nwww.lawcommission.gov.np\ntreatment at home, and the employer shall provide full remuneration during such\na period.\nProvided that the employer shall not be required to provide remuneration\nif the labour is entitled to receive the remuneration facility from the Social\nSecurity Fund for the period of treatment.\n(3) In the case of a labour who is not able to attend the work of the\nenterprise on the ground of medical treatment in the circumstance other than that\nset forth in sub-section (2), the employment of such a labour may not be terminated\nuntil six months.\nProvided that this sub-section shall not be deemed to bar the removal from\nthe service prior to that period if there is a clear recommendation by a medical\ndoctor to the effect that the labour cannot return to the work.\n(4) Notwithstanding anything contained in sub-section (1), in cases\nwhere the labour who is physically incapacitated or has sustained grievous hurt or\ninjury can be engaged in any work suitable to the condition of his or her health,\nthe employer shall engage such a labour in work.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "144", "title": "Notice to be given: (1) Prior to terminating the employment relation in any", "content": "circumstance except when employment is terminated upon action taken for\nmisconduct, the employer or labour shall give a notice as follows to each other:\n(a) Prior to at least one day, in the case of employment for a maximum\nof four weeks,\n(b) Prior to at least seven days, in the case of employment for a period\nof four weeks to one year, and\n(c) Prior to at least thirty days, in the case of employment for a period\nof more than one year.\n(2) Where the employer terminates employment without giving the\nnotice referred to in sub-section (1), the employer shall pay the amount equal to\nthe remuneration for the period requiring the notice to be given to the concerned\nlabour.\n(3) Where the labour terminates employment without giving a notice to\nthe employer pursuant to sub-section (1), the employer may deduct the amount\nequal to the remuneration for the period requiring the notice to be so given from\nthe remuneration payable to the concerned labour.\n66\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "145", "title": "Retrenchment may be made: (1) Where an enterprise faces financial problems", "content": "in its operation or the labours become redundant because of the merger of more\nthan one enterprises or the enterprise needs to be closed down partially or\ncompletely because of any other reason, the employer may retrench the number of\nlabours.\n(2) When retrenching the labours pursuant to sub-section (1), the\nemployer shall, in advance of at least thirty days before the date for retrenchment,\ngive a notice, setting out the reason requiring retrenchment, possible date for\nretrenchment and probable number of labours to be retrenched to the Office and\nthe authorised trade union, if any, of the enterprise or in the absence of such a\nunion, to any trade union which is active in the enterprise or the labour relation\ncommittee.\n(3) After giving the notice pursuant to sub Section (1), the employer\nshall hold discussion with the concerned trade union or the labour relation\ncommittee on the matters concerning the alternatives to the retrenchment of\nlabours and the grounds and conditions for the selection of the labours for\nretrenchment, and the labours may be retrenched as per the agreement reached\nupon the discussion.\n(4) Where the trade union or the labour relation committee does not\nwant to hold discussion pursuant to sub-section (3) or no agreement is reached\nupon the discussion, the employer may, by giving information of that matter to the\nOffice, retrench the labours.\n(5) While retrenching the labours pursuant to this Section, retrenchment\nshall be made generally in the following order:\n(a) foreign labours,\n(b) those labours who have been awarded more punishments\ncomparatively for misconduct,\n(c) labours whose standard of work performance is rather weak,\n(d) labours who have been appointed at the last out of the labours\nengaged in the same type of work.\nProvided that if it is necessary to retrench the labours\nwho were appointed earlier, instead of making retrenchment\nin the order so specified as to retrench those who have been\n67\nwww.lawcommission.gov.np\nappointed at the last, retrenchment may be made by setting\nout the reason for the same.\n(6) Notwithstanding anything contained in sub-section (5), except as\notherwise agreed with the trade union, the office-bearers of the collective\nbargaining committee or the authorized trade union shall be retrenched last in the\norder of priority.\n(7) While retrenching the number of labours, the employer shall pay a\nlump sum amount to be set by calculating at the rate of one month’s basic\nremuneration for each year of his or her service as compensation to a labour who\nhas completed the service period of at least one year.\nProvided that if the service period is less than one year, he or she shall get\nthe compensation proportionately.\n(8) Notwithstanding anything contained in sub-section (7), the labour\nwho is entitled to the unemployment allowance under the social security laws shall\nnot receive the compensation pursuant to sub-section (7).\n(9) Where any enterprise is required to close down the whole or any\npart of the enterprise in pursuance of the order of the Government of Nepal or\nLabour Court in accordance with law or any enterprise in the special economic\nzone is required to retrench its labours, the provisions of sub-sections (1), (2), (3)\nand (4) shall not be applicable.\n(10) Notwithstanding anything contained elsewhere in this Section, the\nprovision contained in this Section shall not be applicable to any employer who\nemploys ten or less than ten labours and makes retrenchment of labours.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "146", "title": "Resumption of operation: (1) Where, for any reason, the retrenchment of its", "content": "labours has been made but the enterprise resumes its operation within two years\nor needs to supply additional labours, the preference for employment shall be\ngiven to the labours retrenched pursuant to Section 145.\n(2) Notwithstanding anything contained in sub-section (1), any other\npersons may be employed if the labour who has been retrenched fail to appear in\nspite of the notice given to him or her as prescribed.\n(3) Where the employer does not give notice or does not employ, the\nconcerned labour may, not later than thirty-five days, make an application to the\nLabour Court.\n(4) Other provisions relating to this matter shall be as prescribed.\n68\nwww.lawcommission.gov.np", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "147", "title": "Compulsory retirement: Any labour who is in regular employment shall get", "content": "compulsory retirement after completing the age of fifty-eight years.\nProvided that if there is a need to make compulsory retirement at an age\nbelow the age of fifty-eight years for the work of a particular nature, provision to\nthat effect may be made in the bye-law by obtaining approval from the Council as\nprescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "148", "title": "Payment of benefits: (1) In the case of an employee of which employment is", "content": "terminated because of misconduct or in any other manner whatsoever, the\nemployer shall pay all amounts including the remuneration, benefits receivable by\nhim or her at the time of such termination to the labour, not later than fifteen days\nof the termination of employment.\n(2) The employer shall extend necessary assistance in the provision of\nsuch amount or benefits that is receivable by the labour from the Social Security\nFund, insurance or other body.\n(3) In the case of failure to pay such remuneration or benefits that is\nreceivable by the labour within the period referred to in sub-section (1) or to\nextend assistance pursuant to sub-section (2), remuneration shall be paid to such\na labour until the amount is paid as if he or she were in the service.\n(4) Where the labour does not appear to receive the remuneration or\nbenefits, the employer may make payment to the labour’s account or deposit the\nsame with the Office, directly.\n(5) Other provisions relating to the deposit and payment of the amount\nreferred to in sub-section (4) shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "149", "title": "Labours to get first priority: Notwithstanding anything contained in other", "content": "prevailing law, in case of closure or liquidation of any enterprise, the remuneration\nor other benefits due and payable to the labours shall be paid with first priority.\nProvided that where the insolvency law is applicable, it shall be dealt with\naccordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "150", "title": "To issue the certificate of experience: Where the labour whose employment has", "content": "been terminated requests for the certificate of experience, the employer shall give\nthe certificate of work experience, stating, inter alia, the period of service and post\nof such a labour.\n69\nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-22", "title": "Chapter-22", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "151", "title": "Formation of Labour Court: (1) The Government of Nepal shall, by a", "content": "notification in the Nepal Gazette, form a required number of labour courts.\n(2) The jurisdiction and seat of the Labour Court to be formed pursuant\nto sub-section (1) shall be as specified in the same notice.\n(3) The Labour Court shall consist of one chairperson and two\nmembers.\n(4) Any sitting judge of the High Court or any person having the\nqualification of becoming a Judge of the High Court shall be qualified to be the\nchairperson or member of the Labour Court.\n(5) Except when a sitting judge of the High Court is appointed, the\ntenure of the chairperson and members of the Labour Court shall be four years.\n(6) The conditions of service and facilities of the chairperson and\nmembers of the Labour Court shall be the same as that of the Judges of the High\nCourt.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "152", "title": "Majority decision to prevail: (1) The chairperson and members shall collectively", "content": "exercise the jurisdiction of the Labour Court.\nProvided that where the chairperson or any one member is absent, even the\nbench of two members may try and adjudicate cases.\n(2) A decision of majority of members shall be deemed to be a decision\nof the Labour Court.\n(3) If the two members constituting the bench hold different opinions,\nsuch opinions shall be submitted to the third member, and the opinion concurred\nby the third member shall be deemed to be a decision of the Labour Court. If the\nchairperson and member hold different opinions, the opinion of the chairperson\nshall be deemed to be a decision of the Labour Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "153", "title": "Powers of Labour Court: The Labour Court may, in the course of deciding a", "content": "case, exercise the following powers, in addition to the powers set forth in this Act\nor the rules framed under this Act:\n(a) To examine witness, evidence,\n(b) To take the defendant’s statement equal to the note of defence, as\nper necessity,\n70\nwww.lawcommission.gov.np\n(c) To order any party who is not made party or opponent in the case,\non the basis of application by such party or of the nature of the case,\nto appear in the course of hearing, and set as a party to the case if\nso required,\n(d) To inspect any place or workplace related to the dispute,\n(e) If the application made by any party to the case submitting that it is\nnecessary to defer the case until any case sub-judice in the Labour\nCourt is finally settled or to continue the same appears to be\nreasonable, notwithstanding the state of the case, to issue an\ninterlocutory order to any party to the case to stop any act for a\ncertain time or give continuity to any act being carried out, with or\nwithout fixing a period,\n(f) To uphold, withhold or alter any direction, decision or order given\nby the Office or the employer,\n(g) The Labour Court shall, in holding the proceeding of and\nadjudicating the case, have the powers as mentioned in the case of\nthe matters set forth in this Act or the rules framed under this Act,\nand the same powers as the District Court may exercise, in the case\nof the other matters..", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "154", "title": "Proceeding against contempt of court: (1) The Labour Court may institute", "content": "proceeding for its contempt.\n(2) Where an act of contempt is established in the proceeding instituted\npursuant to sub Section (1), the Labour Court may impose punishment of a fine\nnot exceeding ten thousand rupees or imprisonment for a term not exceeding six\nmonths or both on the offender.\nProvided that if the offender begs pardon to the satisfaction of the Labour\nCourt, the Labour Court may forgive him or her or absolve him or her of the\npunishment if already determined or reduce such punishment or order not to\nexecute the punishment subject to the compliance with such conditions as\nspecified by the Labour Court, after deferring the punishment on such conditions.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "155", "title": "Power to demand bank guarantee or deposit: If there is a possibility that one", "content": "party will be entitled to receive any amount from the other party when the case\nrunning under this Act is adjudged and there is a likelihood of non-payment of\nsuch amount by such a party, the Labour Court may, for the execution of the\n71\nwww.lawcommission.gov.np\ndecision, require such a party to deposit the amount equivalent to that amount or\nfurnish a bank guarantee covering that amount.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "156", "title": "Power to order payment of interest: (1) Where judgment is made holding any", "content": "party to the case liable to pay compensation or any other cash to the other party,\npayment of such compensation or cash shall be made not later than two months of\nthe date of receipt of notice of the judgment or decision.\n(2) In the event of failure to pay such compensation or cash within the\nperiod referred to in sub-section (1), an interest on such compensation or cash to\nbe set by fifteen percent thereof shall be paid or recovered with effect from the\ndate of judgment in the case.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "157", "title": "Case may be compromised: (1) Notwithstanding the state of the proceeding of a", "content": "case running in the Labour Court under this Act, the Labour Court may, on the\nbasis of the application made by the concerned party, give permission to\ncompromise or defer or withdraw such a case.\n(2) When compromising or deferring or withdrawing the case pursuant\nto sub-section (1), no fine, royalty or fee of any kind shall be charged.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "158", "title": "High Court to perform functions of Labour Court: (1) Notwithstanding", "content": "anything contained elsewhere in this Chapter, the Government of Nepal may, by a\nnotification in the Nepal Gazette, assign the functions of the Labour Court to any\nHigh Court upon specifying its jurisdiction.\n(2) The High Court assigned pursuant to sub-section (1) may exercise\nall such powers as may be exercisable by the Labour Court pursuant to this Chapter\nwhile trying and adjudicating the case.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "159", "title": "To forward the matter to the body having jurisdiction: In making a decision", "content": "on a case filed in the Labour Court or the Office pursuant to this Act or the\nprevailing law that it has no jurisdiction, the Labour Court or Office shall appoint\nthe date for appearance and send the parties, along with its case-file, to the\nconcerned competent body for a decision.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "160", "title": "Procedures of the cases: Other provisions relating to the procedures of the cases", "content": "to be filed in the Labour Court shall be as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "161", "title": "Appeal to the Supreme Court: (1) Any party who is dissatisfied with the order", "content": "or judgment made by the Labour Court in a case originally tried and adjudicated\nby the Labour Court may make an appeal to the Supreme Court within thirty-five\ndays of the date of knowledge of such an order or judgment.\n72\nwww.lawcommission.gov.np\n(2) Any decision made on appeal by the Labour Court shall be final.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-23", "title": "Chapter-23", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "162", "title": "Right to make complaint: Where any person, employer, labour or office-bearer", "content": "acts in violation of this Act or the rules framed under this Act, the party who is\naggrieved by such act or the concerned trade union with the written consent of the\naggrieved party may make a complaint to the authority competent to make a\ndecision pursuant to Section 163 or 164, not later than six months from the date\nof commission of such act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "163", "title": "Power of the Department or Office to decide: (1) The Department may conduct", "content": "necessary inquiry into a complaint made on any of the following matters and do\nas follows:\n(a) To issue necessary order subject to this Act and impose a fine not\nexceeding two hundred thousand rupees on any person that supplies\nlabours without obtaining any license pursuant to this Act and any\nperson that hires and employs labours through such a labour\nsupplier,\n(b) To impose, on the basis of the number of such labours, a fine not\nexceeding two hundred thousand rupees on any person who employs\na foreigner without obtaining the labour permit pursuant to this Act,\nand an additional fine at the rate of five thousand rupees per person\nper month in case such a person continues to employ such a\nforeigner in spite of the punishment so imposed,\n(c) To issue an order to maintain equality by imposing a fine not\nexceeding one hundred thousand rupees on any person who\ndiscriminates labours at the time of employing or during\nemployment contrary to Chapter 2,\n(d) To order a person who employs a labour without giving an\nappointment letter or without entering into an employment contract,\nto give an appoint letter or to enter into an employment contract\nupon imposing on such a person a fine not exceeding five hundred\nthousand rupees at the rate of ten thousand rupees per labour,\n73\nwww.lawcommission.gov.np\n(e) To take departmental action pursuant to the prevailing law against\nany inspector who causes loss or damage by committing any act\nrecklessly or with ulterior motive pursuant to Chapter 15,\n(f) To give necessary order in case any person exercises any unfair\nlabour practice or makes transfer contrary to this Act to the\ndetriment of the labour or performs any act, action relating to\npromotion contrary to the bye-law of the enterprise,\n(g) To give necessary direction to the concerned Office in case it does\nnot perform any act, action required to be performed by it within a\ncertain period, pursuant to this Act and the rules framed under this\nAct, even within thirty days of the expiry of that period,\n(h) To do necessary work for the settlement of a dispute, if any, arising\nbetween a labour supplier and a main employer as to the\nremuneration and benefits to be provided to labours.\n(2) The Office may make necessary inquiry into an application made on\nany of the following matters and do as follows:\n(a) To require the employer who employs a labour by paying\nremuneration below the minimum remuneration or deducts\nremuneration or benefits contrary to this Act or the rules framed\nunder this Act to pay the deducted amount and a compensation not\nexceeding two times of such amount to the concerned labour,\n(b) To impose a fine not exceeding twenty thousand rupees on any\nemployer, labour or other person who hinders a government\nemployee in the course of performance of his or her duties or submit\nfalse description or makes false statement or exerts or attempts to\nexert undue influence in any way,\n(c) To impose a fine at the rate of ten thousand rupees per apprentice or\ntrainee on an employer who engages any person as an apprentice or\ntrainee contrary to this Act, issue an order to employ such an\napprentice or trainee on regular employment and to pay the\nremuneration and benefits accordingly,\n(d) To order recovering such compensation and damages that is two\ntimes higher than the compensation from the employer who does not\ndeposit such amount of gratuity and of provident fund or contribute\n74\nwww.lawcommission.gov.np\nsuch amount to the social security fund as may be receivable by the\nlabour pursuant to this Act or the rules framed under this Act or pay\nmedical expenses or make insurance for compensation,\n(e) To give direction to the employer who makes retrenchment contrary\nto this Act or in a discriminatory manner to refrain from doing so,\n(f) To give necessary direction to the employer who terminates the\nemployment or prevents any labour from attending the work\ncontrary to this Act or the rules or bye-law framed under this Act.\n(3) Notwithstanding anything contained elsewhere in this Act, nothing\nshall be deemed to bar the making of an application by any labour to the employee\nto pursue the personal dispute settlement process and settle the dispute\naccordingly.\n(4) Any complaint made to the Department or the Office shall be\nproceeded with and settled as prescribed.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "164", "title": "Decision may be made by the Labour Court: (1) If any person engages any one", "content": "in forced labour, the Labour Court may punish such a person with imprisonment\nfor a term not exceeding two years or a fine not exceeding five hundred thousand\nrupees or both and require such person to pay remuneration, allowance and\nbenefits including damages that is two times of such amount to the labour.\nProvided that if any person takes another person outside Nepal and engages\nhim or her in forced labour, it shall also order the recovery of expenses incurred\nin bringing that other person into Nepal.\n(2) If any person dies or suffers grievous hurt as a result of violation,\nknowingly or recklessly, of any provision relating to occupational safety and\nhealth set forth in this Act or the rules framed under this Act or any person dies as\nor gets any of his or her bodily organ disabled or his or her physical or mental\nstate becomes adversely affected a result of infection of occupational disease\ncaused as a result of performance or non-performance of any act or any part of the\nbody becomes disabled or physical or mental state, the person who commits such\nact shall be liable to the punishment, if any, provided for in the prevailing law and,\nfailing such provision, to the punishment of imprisonment for a term not exceeding\ntwo years, and the Labour Court may require such person to pay appropriate\ncompensation to the aggrieved person.\n75\nwww.lawcommission.gov.np\n(3) Where a body corporate commits any offence punishable under this\nAct, such body shall be punished with the fine, and if imprisonment is also\nimposable for such offence, the chief executive of such body shall be imprisoned\naccordingly.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "165", "title": "Appeal: (1) Any person who is not satisfied with any order or decision made by", "content": "the Department or Office in accordance with this Act or the rules framed under\nthis Act may make an appeal to the Labour Court within thirty-five days.\n(2) Any labour who is not satisfied with any decision made by the\nemployer to terminate employment or with punishment imposed with respect to\nmisconduct may make an appeal to the Labour Court within thirty-five days of the\ndate of receipt of a notice of that decision or punishment.\n(3) Notwithstanding anything contained in sub-section (2), nothing\nshall be deemed to bar the making of appeal accordingly if the bye-law of any\nenterprise provides for internal appeal.\n(4) The aggrieved party may make an appeal to the Labour Court within\nthirty-five days of the date of receipt of a notice of the decision made by the appeal\nhearing body or of the date of sixty days of the date on which appeal was made if\nsuch party does not receive a notice about the decision on appeal within that\nperiod.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "166", "title": "Decisions to be executed: (1) After a decision or judgment made by the Labour", "content": "Court pursuant to this Act has become final or the limitation for making appeal\nhas expired, the concerned party shall execute such decision or judgment.\n(2) The concerned party shall execute, in good faith, any agreement\nreached in respect of an individual or collective claim between a labour or trade\nunion and the employer bilaterally or before the Office or any other body or\nauthority or any arbitral award.\n(3) Where the concerned party fails to execute the agreement or\ndecision pursuant to sub-section (1) or (2), the other party may on his or her own\nor through the trade union or employers’ association make an application to the\nOffice for that purpose.\n(4) On receipt of the application pursuant to sub-section (3), the Office\nshall write to the concerned employer or labour for the execution of such\nagreement, decision or judgment.\n76\nwww.lawcommission.gov.np\n(5) If so asked pursuant to sub-section (4), the concerned employer or\nlabour shall execute such an agreement, decision or judgment within fifteen days\nfrom the date of receipt of such direction.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "167", "title": "Power of the Office to have execution of decisions: (1) Where the decision,", "content": "judgment or agreement is not executed pursuant to Section 166, the concerned\nparty may make an application to the Office.\n(2) On receipt of the application pursuant to sub-section (1), the Office\nmay cause such a decision, judgment or agreement to be executed by adopting any\nor all of the following measures vis-à-vis the employer, enterprise or labour who\nhas to execute such decision, judgment or agreement:\n(a) To send a request to the concerned body or authority to withhold\nany immovable property or auction the property,\n(b) To send a request to freeze a bank account,\n(c) To send a request for the suspension or withholding of such\nconcessions or facilities as may be enjoyable pursuant to the\nprevailing law,\n(d) To suspend the labour permit or license of the concerned party,\n(e) To make any other appropriate order.\n(3) If so requested by the Office to do any act referred to in sub-section\n(2), the concerned body shall do accordingly.\n(4) If the decision or judgment is not executed within three months from\nthe date when the application was made pursuant to sub-section (1) or within\nfifteen days of the completion of the process referred to in sub-sections (2) and (3)\nor such a decision or judgment is challenged legally, a complaint may be made in\nthe Labour Court for punishment pursuant to Section 168.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "168", "title": "Power to impose punishment in the event of non-execution of judgment,", "content": "compromise or agreement: (1) The Labour Court shall give a notice prescribing\nthe time limit to the concerned party for the execution of any judgment on labour\nrelated matters made by the Labour Court or the Supreme Court.\n(2) The Labour Court may impose the punishment with a fine not\nexceeding one hundred thousand rupees or with imprisonment for a term not\nexceeding one year on any employer or labour who fails to execute or delays or\nlingers the implementation of the order given by the Office for the execution of\nthe order, judgment made by the Labour Court or arbitral award or understanding\n77\nwww.lawcommission.gov.np\nor agreement entered into between the employer and the labour pursuant to this\nAct.\nProvided that if the order, judgment, compromise, agreement or\nunderstanding is executed within the period prescribed by the Labour Court, the\nLabour Court may annul such punishment or give partial or full exemption from\nthe enforcement of such punishment if already sentenced.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter-24", "title": "Chapter-24", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "169", "title": "Procedure relating to service of notice: (1) A process or notice sent by the", "content": "employer to the labour or vice versa shall immediately be acknowledged and a\nreceipt of such acknowledgment, provided.\n(2) Where a process or notice could not be served in accordance with\nsub-section (1), such a process or notice shall be deemed to have been received by\nthe concerned party if it is sent by registered courier or post to his or her address,\nwith one copy thereof being posted at the workplace, and a memorandum being\nexecuted in witness of three persons, and information thereof is given to the\nOffice.\nProvided that in the case of the application or notice given by the labour, it\nis not required to post it at the workplace.\n(3) Where any one refuses to accept such a process or notice, it may be\nsent through fax or email or other electronic means of communication to him or\nher. If so sent, such a process or notice shall be deemed to have been served except\nas otherwise proved.\n(4) Where, in the case of any matter required to be informed by the\nemployer collectively, such information shall be deemed to have been received by\nall the labours if the notice thereof is posted on the notice board of the workplace\nand written information thereof is given to the trade unions active in the enterprise.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "170", "title": "Fixation of basic remuneration: (1) The basic remuneration of the labour on", "content": "task-based employment shall be determined as prescribed.\nProvided that if not so determined, the minimum remuneration fixed for the\nlabours shall be regarded as the basic remuneration.\n78\nwww.lawcommission.gov.np\n(2) In the case of labours on piece rate work, the rate of wage per piece\nshall be determined as prescribed on the basis of the minimum remuneration fixed\npursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "171", "title": "Special provisions relating to managers and managerial level labours: (1)", "content": "Notwithstanding anything contained elsewhere in this Act, nothing contained in\nthis Act shall be deemed to bar the hiring of a managerial level labour working in\nthe capacity of chief executive on time based employment, fixing of terms and\nbenefits of service and termination of his or her service.\n(2) The managers and managerial level labours are not allowed to\nsubmit collective demands or take part in collective bargaining or in a strike, on\nbehalf of any trade union.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "172", "title": "Entitlement to remuneration and other benefits: (1) Where a labour who is", "content": "terminated from the employment is reinstated in employment by an order or\ndecision of the Office or Department or Labour Court, such labour shall be entitled\nto receive the remuneration and other benefits from the employer for the period\nfrom the date of termination to the date of reinstatement.\n(2) Nothing contained in this Act shall be deemed to bar the making of\njudgment enabling the labour to receive a reasonable amount as compensation in\naddition to the amount referred to in sub-section (1) from the employer, instead of\nreinstating such labour on the basis of the merits of the case.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "173", "title": "Increment of insurance amount: On recommendation of the Council, the", "content": "Government of Nepal may, by a notification in the Nepal Gazette, periodically\nincrease the medical insurance and accidental insurance amount specified in this\nAct.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "174", "title": "Delegation of authority: The Ministry or Department or Office may so delegate", "content": "any or all of the powers conferred on it by this Act that such power is exercisable\nby any office or officer. If such delegation is made, a notice thereof shall be\npublished in the Nepal Gazette.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "175", "title": "Saving of acts done in good faith: No action shall be instituted against any labour", "content": "inspector, occupational safety and health inspector or any officer or employer or\nlabour deputed in inspection for the loss or damage, if any, caused to any person\nas a result of any act done or attempted to be done in good faith in the course of\nperforming his or her duties.\n79\nwww.lawcommission.gov.np\nProvided that such person shall be personally liable with respect to any act\ndone knowingly or with bad intention.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "176", "title": "Special powers of the Ministry: If information is received that the party is", "content": "compelled to suffer harassment because of failure to decide any application made\nto the Office or Department for a long time, except for the matter which is sub\njudice in the Labour Court under this Act or if it seems appropriate that such\napplication is to be proceeded with by the Ministry because of the subject matter\ncontained in the application being complex, nothing contained elsewhere in this\nAct shall be deemed to bar the Ministry form examining and deciding such\napplication. The decision so made shall be deemed to be a decision made by the\nbody of first instance, and the party who is not satisfied with such decision may\nmake an appeal to the Labour Court.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "177", "title": "Labour coordination committee: (1) There shall be a central level labour", "content": "coordination committee consisting of such members as prescribed, under the\nchairpersonship of the Director General of the Department.\n(2) The functions, duties and powers of the committee shall be as\nprescribed", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "178", "title": "Transitional provisions: (1) The labours engaged in permanent service at the time", "content": "of commencement of this Act shall ipso facto be deemed to be the labours in\nregular employment pursuant to this Act.\n(2) The labours employed on contract, daily wage basis or otherwise at\nthe time of commencement of this Act shall be required to make the employment\ncontract pursuant to Chapter 3. Nothing contained in this Act shall be deemed to\nbar the making of adjustment of the remuneration and benefits receivable at the\ntime of making such employment contract to the provident fund amount and other\nbenefits payable pursuant to this Act not later than three months of the\ncommencement of this Act.\n(3) Nothing contained in this Act shall be deemed to be prejudicial to\nthe conditions of service and benefits of any labour who is receiving the benefits\nin excess of that set forth in the Act under the prevailing law or collective\nagreement at the time of the commencement of this Act.\n(4) For the purpose of sub-section (3), the benefits that remain after\npaying the benefits specified in the Act to the prescribed body shall be provided\nby adjusting the same in other headings.\n80\nwww.lawcommission.gov.np\n(5) Where any judgment made by the Office, Labour Court or other\ncourt under the Labour Act, 1992 (2048) and Trade Union Act, 1992 (2049) before\nthe commencement of this Act has not been executed and an application is made\nwithin one year of the date of the commencement of this Act, such a judgment,\ndecision or order shall be executed or caused to be executed as if it were made in\naccordance with this Act.\n(6) The welfare fund established under Section 37 of the Labour Act,\n1992 (2048) and Section 13 of the Bonus Act, 1974 (2030) shall continue its\noperation until a separate law relating to social security is made.\n(7) The Court in existence at the time of the commencement of this Act\nshall exist until the formation of the court pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "179", "title": "This Act to prevail: The matters contained in this Act and the rules framed under", "content": "this Act shall be governed by this Act and Regulation and the other matters, by the\nprevailing laws.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "180", "title": "This Act not to apply: (1) The following matters shall be governed as follows:", "content": "(a) This Act shall not apply to the Nepal army, Nepal Police, Armed\nPolice Force and National Investigation.\n(b) The prevailing law relating to civil service shall apply in the case of\nthe civil service.\n(2) Where the prevailing law provides for the conditions and benefits\nof service in relation to the service established under a special law and the special\neconomic zone, such service shall be governed accordingly.\n(3) Where the prevailing law has no provision in relation to the\nremuneration, conditions and benefits of service of any labour, the provisions of\nthis Act shall ipso facto apply in the case of the remuneration, conditions and\nbenefits of service of such labour.\n(4) When making any decision, order or judgment that this Act will not\napply to any labour, such decision, order or judgment shall be made setting out,\ninter alia, which law provides for the rights and benefits conferred by this Act in\nthe case of such labour.\n(5) Where the employer of an enterprise to which the Working\nJournalists Act, 2051 applies executes the employment contract pursuant to this\nAct or any agreement thereby making applicable the provisions of this Act\n81\nwww.lawcommission.gov.np\nbetween the employer and the labour of such enterprise, this Act shall also apply\nto such labour.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "181", "title": "To frame and implement directives and procedures: (1) The Ministry may, for", "content": "the purpose of implementation of this Act or the rules framed under this Act, frame\nand implement necessary directives and procedures.\n(2) Employers' commodities associations or federations and trade union\nassociations or federations may frame and implement codes of good labour\npractice on policy matters relating to the labour.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "182", "title": "Powers to frame rules: (1) The Government of Nepal may frame necessary rules", "content": "for the implementation of this Act.\n(2) When framing rules pursuant to sub-section (1), separate rules may\nbe framed in the case of businesses, services and industries of special nature or of\nthe informal sector.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "183", "title": "Repeal and saving: (1) The following Acts have been repealed:", "content": "(a) The Labour Act, 1992 (2048),\n(b) The Industrial Apprenticeship and Training Act, 1983 (2039),\n(c) The Retirement Fund Act, 1986 (2042).\n(2) The cases filed and sub judice under the Acts set forth in sub-section\n(1) shall be transferred to the Labour Court.\n(3) Any acts and actions performed under the Acts set forth in sub-\nsection (1) shall be deemed to have been performed under this Act.\n82", "children": []}]}]$CODEx585f90ccad$::jsonb,$CODEx0e7c18d296$The-Labor-Act-2017-2074.pdf$CODEx0e7c18d296$) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, original_title=EXCLUDED.original_title, document_type=EXCLUDED.document_type, year_bs=EXCLUDED.year_bs, year_ad=EXCLUDED.year_ad, total_pages=EXCLUDED.total_pages, nodes=EXCLUDED.nodes, source_filename=EXCLUDED.source_filename;
